      "path": "src/openbiliclaw/runtime/event_ingress.py",
      "content": "\"\"\"Durable, idempotent ingress for canonical behavioral events.\"\"\"\n\nfrom __future__ import annotations\n\nimport inspect\nimport logging\nfrom dataclasses import dataclass, field\nfrom types import SimpleNamespace\nfrom typing import TYPE_CHECKING, Any\n\nfrom openbiliclaw.memory.manager import SUPPORTED_EVENT_TYPES\n\nif TYPE_CHECKING:\n    from collections.abc import Awaitable, Callable\n\nlogger = logging.getLogger(__name__)\n\n\n@dataclass(frozen=True)\nclass EventIngressItemReceipt:\n    \"\"\"Outcome for one input position in an ingress batch.\"\"\"\n\n    index: int\n    event_type: str\n    event_id: int = 0\n    inserted: bool = False\n    duplicate: bool = False\n    error: str = \"\"\n\n\n@dataclass(frozen=True)\nclass EventIngressReceipt:\n    \"\"\"Durable acceptance summary returned to compatibility adapters.\"\"\"\n\n    items: tuple[EventIngressItemReceipt, ...] = field(default_factory=tuple)\n    accepted: int = 0\n    inserted: int = 0\n    duplicates: int = 0\n    rejected: int = 0\n\n\nclass EventIngressService:\n    \"\"\"Validate canonical events, commit them atomically, then wake one owner.\n\n    The wake is only a hint. SQLite rows and producer-owned ``ingest_key``\n    values are the source of truth, so a crash before/after wake loses no fact.\n    \"\"\"\n\n    def __init__(\n        self,\n        memory_manager: Any,\n        *,\n        memory_manager_resolver: Callable[[], Any] | None = None,\n        prepare_owner: Callable[[], Awaitable[object] | object] | None = None,\n        wake: Callable[[], object] | None = None,\n    ) -> None:\n        self._memory_manager = memory_manager\n        self._memory_manager_resolver = memory_manager_resolver\n        self._prepare_owner = prepare_owner\n        self._wake = wake\n        self._compat_next_event_id = 1\n\n    async def accept(\n        self,\n        event: dict[str, Any],\n        *,\n        producer: str,\n    ) -> EventIngressReceipt:\n        \"\"\"Accept one event through the batch transaction path.\"\"\"\n        return await self.accept_batch([event], producer=producer)\n\n    async def accept_batch(\n        self,\n        events: list[dict[str, Any]],\n        *,\n        producer: str,\n    ) -> EventIngressReceipt:\n        \"\"\"Persist every valid input in one transaction and retain rejections.\"\"\"\n        producer_name = self._validate_producer(producer)\n        valid: list[dict[str, Any]] = []\n        valid_indexes: list[int] = []\n        receipts: dict[int, EventIngressItemReceipt] = {}\n        for index, raw_event in enumerate(events):\n            try:\n                event = self._validated_event(raw_event, producer=producer_name)\n            except ValueError as exc:\n                event_type = \"\"\n                if isinstance(raw_event, dict):\n                    event_type = str(\n                        raw_event.get(\"event_type\") or raw_event.get(\"type\") or \"\"\n                    ).strip()\n                receipts[index] = EventIngressItemReceipt(\n                    index=index,\n                    event_type=event_type,\n                    error=str(exc),\n                )\n                continue\n            valid.append(event)\n            valid_indexes.append(index)\n\n        if valid:\n            await self._call_prepare_owner()\n            memory_manager = (\n                self._memory_manager_resolver()\n                if self._memory_manager_resolver is not None\n                else self._memory_manager\n            )\n            persist = getattr(memory_manager, \"persist_events_with_receipts\", None)\n            if callable(persist):\n                stored = await persist(valid)\n            else:\n                # Compatibility for narrow injected/legacy test doubles only;\n                # production MemoryManager always exposes the atomic receipt\n                # API above.\n                propagate_many = getattr(memory_manager, \"propagate_events\", None)\n                propagate_one = getattr(memory_manager, \"propagate_event\", None)\n                if callable(propagate_many):\n                    result = propagate_many(valid)\n                    if inspect.isawaitable(result):\n                        await result\n                elif callable(propagate_one):\n                    for event in valid:\n                        result = propagate_one(event)\n                        if inspect.isawaitable(result):\n                            await result\n                else:\n                    raise RuntimeError(\"memory manager has no durable event persistence API\")\n                stored = []\n                for event in valid:\n                    stored.append(\n                        SimpleNamespace(\n                            event_id=self._compat_next_event_id,\n                            event_type=str(event[\"event_type\"]),\n                            inserted=True,\n                            duplicate=False,\n                        )\n                    )\n                    self._compat_next_event_id += 1\n            if len(stored) != len(valid):\n                raise RuntimeError(\"event receipt count did not match accepted input count\")\n            for index, result in zip(valid_indexes, stored, strict=True):\n                receipts[index] = EventIngressItemReceipt(\n                    index=index,\n                    event_type=str(result.event_type),\n                    event_id=int(result.event_id),\n                    inserted=bool(result.inserted),\n                    duplicate=bool(result.duplicate),\n                )\n            self._wake_owner()\n\n        ordered = tuple(receipts[index] for index in range(len(events)))\n        inserted = sum(1 for item in ordered if item.inserted)\n        duplicates = sum(1 for item in ordered if item.duplicate)\n        rejected = sum(1 for item in ordered if item.error)\n        return EventIngressReceipt(\n            items=ordered,\n            accepted=inserted + duplicates,\n            inserted=inserted,\n            duplicates=duplicates,\n            rejected=rejected,\n        )\n\n    async def _call_prepare_owner(self) -> None:\n        prepare = self._prepare_owner\n        if prepare is None:\n            return\n        result = prepare()\n        if inspect.isawaitable(result):\n            await result\n\n    def _wake_owner(self) -> None:\n        wake = self._wake\n        if wake is not None:\n            try:\n                wake()\n            except Exception:\n                # The durable row/cursor recovery loop is authoritative; a wake\n                # is only a latency hint and can never undo a committed fact.\n                logger.warning(\"event ingress owner wake failed after commit\", exc_info=True)\n\n    @staticmethod\n    def _validate_producer(producer: str) -> str:\n        normalized = str(producer or \"\").strip().lower()\n        if not normalized or len(normalized) > 80:\n            raise ValueError(\"producer must be a non-empty bounded name\")\n        if any(character.isspace() or ord(character) < 32 for character in normalized):\n            raise ValueError(\"producer contains invalid characters\")\n        return normalized\n\n    @staticmethod\n    def _validated_event(raw_event: object, *, producer: str) -> dict[str, Any]:\n        if not isinstance(raw_event, dict):\n            raise ValueError(\"event must be an object\")\n        event = dict(raw_event)\n        event_type = str(event.get(\"event_type\") or event.get(\"type\") or \"\").strip()\n        if event_type not in SUPPORTED_EVENT_TYPES:\n            raise ValueError(f\"Unsupported event type: {event_type or 'unknown'}\")\n        metadata = event.get(\"metadata\", {})\n        if not isinstance(metadata, dict):\n            raise ValueError(\"Event metadata must be an object\")\n        event[\"event_type\"] = event_type\n        event[\"metadata\"] = dict(metadata)\n        raw_key = str(event.get(\"ingest_key\", \"\") or \"\").strip()\n        if raw_key:\n            namespaced = f\"{producer}:{raw_key}\"\n            if len(namespaced) > 512:\n                raise ValueError(\"ingest_key exceeds 512 characters\")\n            event[\"ingest_key\"] = namespaced\n        else:\n            event[\"ingest_key\"] = \"\"\n        return event\n"
    },
    {
      "path": "src/openbiliclaw/agent/tools/feedback_tools.py",
      "content": "\"\"\"Recommendation feedback and local save tools (M3, soft_write).\n\n- ``submit_feedback`` mirrors the durable ingest flow of\n  ``integrations/openclaw/operations.py::submit_feedback`` and the\n  ``POST /api/feedback`` endpoint: build a canonical feedback event, accept it\n  through ``EventIngressService`` (idempotent via ``ingest_key``), project it\n  onto the recommendation row, then fire the non-blocking cognition hook.\n- ``save_item`` mirrors ``operations.py::save_local``: local-only membership\n  through ``SavedSyncService.save_local(..., auto_sync=False)`` — nothing is\n  written to any platform account (L3 对外动作 stays out of v1).\n\"\"\"\n\nfrom __future__ import annotations\n\nimport logging\nimport uuid\nfrom typing import TYPE_CHECKING, Any\n\nfrom .common import maybe_await, require_component, short\nfrom .registry import Tool\n\nif TYPE_CHECKING:\n    from .context import AgentToolContext\n\nlogger = logging.getLogger(__name__)\n\n_FEEDBACK_TYPE_LABELS = {\n    \"like\": \"点赞\",\n    \"dislike\": \"点踩\",\n    \"dismiss\": \"屏蔽\",\n    \"comment\": \"评论\",\n}\n_SAVED_KIND_LABELS = {\n    \"favorite\": \"收藏清单\",\n    \"watch_later\": \"稍后再看\",\n}\n\n\ndef build_feedback_tools(ctx: AgentToolContext) -> list[Tool]:\n    \"\"\"Build the soft-write feedback/save tools bound to ``ctx``.\"\"\"\n    return [\n        Tool(\n            name=\"submit_feedback\",\n            description=(\n                \"对一条推荐提交反馈：like 点赞 / dislike 点踩 / dismiss 屏蔽 / comment 评论\"\n                \"（comment 必须带 note）。recommendation_id 可通过推荐历史或对话上下文获得。\"\n                \"反馈会进入统一兴趣线，影响后续推荐。\"\n            ),\n            permission_level=\"soft_write\",\n            parameters={\n                \"type\": \"object\",\n                \"properties\": {\n                    \"recommendation_id\": {\n                        \"type\": \"integer\",\n                        \"description\": \"推荐记录 ID\",\n                    },\n                    \"feedback_type\": {\n                        \"type\": \"string\",\n                        \"enum\": [\"like\", \"dislike\", \"dismiss\", \"comment\"],\n                        \"description\": \"反馈类型\",\n                    },\n                    \"note\": {\"type\": \"string\", \"description\": \"备注/评论内容，可空\"},\n                    \"request_id\": {\n                        \"type\": \"string\",\n                        \"description\": \"幂等键（同一请求重试时去重），可空，缺省自动生成\",\n                    },\n                },\n                \"required\": [\"recommendation_id\", \"feedback_type\"],\n                \"additionalProperties\": False,\n            },\n            handler=lambda args: _submit_feedback(ctx, args),\n        ),\n        Tool(\n            name=\"save_item\",\n            description=(\n                \"把一条内容保存到本地清单：favorite 收藏 / watch_later 稍后再看。\"\n                \"只在本地记录，不同步到 B 站等平台账号。\"\n            ),\n            permission_level=\"soft_write\",\n            parameters={\n                \"type\": \"object\",\n                \"properties\": {\n                    \"content_id\": {\n                        \"type\": \"string\",\n                        \"description\": \"内容 ID（如 BV 号）\",\n                    },\n                    \"source_platform\": {\n                        \"type\": \"string\",\n                        \"description\": \"来源平台，默认 bilibili\",\n                    },\n                    \"list_kind\": {\n                        \"type\": \"string\",\n                        \"enum\": [\"favorite\", \"watch_later\"],\n                        \"description\": \"目标清单，默认 favorite\",\n                    },\n                    \"title\": {\"type\": \"string\", \"description\": \"标题，可空\"},\n                    \"content_url\": {\"type\": \"string\", \"description\": \"链接，可空\"},\n                    \"content_type\": {\n                        \"type\": \"string\",\n                        \"description\": \"内容形态（video/note/tweet 等），默认 video\",\n                    },\n                    \"author_name\": {\"type\": \"string\", \"description\": \"作者，可空\"},\n                    \"note\": {\"type\": \"string\", \"description\": \"备注，可空\"},\n                },\n                \"required\": [\"content_id\"],\n                \"additionalProperties\": False,\n            },\n            handler=lambda args: _save_item(ctx, args),\n        ),\n    ]\n\n\nasync def _submit_feedback(ctx: AgentToolContext, args: dict[str, Any]) -> str:\n    db = require_component(ctx.database, \"database\")\n    ingress = require_component(ctx.event_ingress, \"event_ingress\")\n\n    raw_id = args.get(\"recommendation_id\")\n    try:\n        recommendation_id = int(raw_id) if raw_id is not None else 0\n    except (TypeError, ValueError):\n        return f\"recommendation_id 无效: {raw_id}。\"\n    feedback_type = str(args.get(\"feedback_type\") or \"\").strip().lower()\n    note = str(args.get(\"note\") or \"\").strip()\n    request_id = str(args.get(\"request_id\") or \"\").strip() or f\"chat-agent-{uuid.uuid4()}\"\n\n    if feedback_type not in _FEEDBACK_TYPE_LABELS:\n        return f\"不支持的反馈类型: {feedback_type}。\"\n    if feedback_type == \"comment\" and not note:\n        return \"评论反馈必须带 note。\"\n\n    recommendation = await maybe_await(db.get_recommendation_by_id(recommendation_id))\n    if recommendation is None:\n        return f\"未找到 ID 为 {recommendation_id} 的推荐记录。\"\n    title = str(recommendation.get(\"title\") or \"\")\n\n    from openbiliclaw.sources.event_format import build_event\n\n    event = build_event(\n        event_type=\"feedback\",\n        source_platform=str(recommendation.get(\"source_platform\") or \"bilibili\"),\n        title=title,\n        metadata={\n            \"recommendation_id\": recommendation_id,\n            \"bvid\": recommendation.get(\"bvid\", \"\"),\n            \"feedback_type\": feedback_type,\n            \"feedback_note\": note,\n            \"event_namespace\": \"recommendation\",\n            \"profile_update_owner\": \"content_feedback\",\n        },\n    )\n    event[\"ingest_key\"] = request_id\n    receipt = await maybe_await(ingress.accept(event, producer=\"chat_agent\"))\n    if receipt.accepted != 1 or receipt.rejected or not receipt.items:\n        reason = receipt.items[0].error if receipt.items else \"rejected\"\n        return f\"反馈事件被拒绝: {reason}\"\n    item_receipt = receipt.items[0]\n\n    label = _FEEDBACK_TYPE_LABELS[feedback_type]\n    if item_receipt.duplicate:\n        return f\"该反馈已提交过（幂等去重），未重复记录：「{short(title, 40)}」的{label}。\"\n\n    # Durable first write is the commit boundary; the projection is a\n    # retryable repair, same shape as the OpenClaw adapter path.\n    await maybe_await(\n        db.update_recommendation_feedback(\n            recommendation_id,\n            feedback_type=feedback_type,\n            feedback_note=note,\n        )\n    )\n\n    hook = getattr(ctx.soul_engine, \"record_immediate_feedback_cognition\", None)\n    if item_receipt.inserted and callable(hook):\n        try:\n            await maybe_await(hook(feedback_type=feedback_type, title=title, note=note))\n        except Exception:\n            logger.warning(\"feedback cognition follow-up deferred\", exc_info=True)\n\n    return f\"已记录对「{short(title, 40)}」的{label}反馈（事件 #{item_receipt.event_id}）。\"\n\n\nasync def _save_item(ctx: AgentToolContext, args: dict[str, Any]) -> str:\n    service = require_component(ctx.saved_sync_service, \"saved_sync_service\")\n\n    content_id = str(args.get(\"content_id\") or \"\").strip()\n    if not content_id:\n        return \"content_id 不能为空。\"\n    list_kind = str(args.get(\"list_kind\") or \"favorite\").strip().lower()\n    if list_kind not in _SAVED_KIND_LABELS:\n        return f\"未知清单类型: {list_kind}（可选: favorite / watch_later）\"\n\n    from openbiliclaw.saved_sync.models import SavedItemInput\n\n    item = SavedItemInput(\n        source_platform=str(args.get(\"source_platform\") or \"bilibili\").strip().lower(),\n        content_id=content_id,\n        content_url=str(args.get(\"content_url\") or \"\"),\n        content_type=str(args.get(\"content_type\") or \"video\"),\n        title=str(args.get(\"title\") or \"\"),\n        author_name=str(args.get(\"author_name\") or \"\"),\n    )\n    result = await maybe_await(\n        service.save_local(\n            list_kind, item, note=str(args.get(\"note\") or \"\").strip(), auto_sync=False\n        )\n    )\n    label = _SAVED_KIND_LABELS[list_kind]\n    display = short(args.get(\"title\") or content_id, 40)\n    if getattr(result, \"saved\", False):\n        return f\"已保存到{label}：{display}（仅本地记录，未同步平台账号）。\"\n    return f\"保存失败：{display} 未写入{label}。\"\n"
    },
    {
      "path": "src/openbiliclaw/runtime/init_coordinator.py",
      "content": "\"\"\"Coordinator for guided (GUI) initialization.\n\nOwns the init lifecycle on a *live* backend (gui-init spec §5):\n\n* single-flight start (TOCTOU) via the ``init_runs`` reservation,\n* the **single writer** to the status store + progress events,\n* the per-run ``enqueued_task_ids`` set that writer-gating consults to let\n  init's own bootstrap task-results through,\n* cooperative cancel of the background task.\n\nIt holds the :class:`RuntimeContext` (not direct component references) and\nreads ``ctx.database`` / ``ctx.event_hub`` / ``ctx.runtime_controller`` lazily\nso it always uses the current instances after a config-driven rebuild swaps\nthem (review R2 A-1).\n\"\"\"\n\nfrom __future__ import annotations\n\nimport asyncio\nimport contextlib\nimport json\nimport logging\nfrom datetime import UTC, datetime\nfrom typing import TYPE_CHECKING, Any\n\nif TYPE_CHECKING:\n    from collections.abc import Sequence\n\n_TOTAL_STAGES = 4\n_STAGE_LABELS = {\n    1: \"拉取数据\",\n    2: \"分析偏好\",\n    3: \"生成并保存完整画像\",\n    4: \"生成首轮可用推荐\",\n}\n_ACTIVE = (\"starting\", \"running\")\n_ORPHAN_HEARTBEAT_SECONDS = 120.0\nlogger = logging.getLogger(__name__)\n\n\n# No per-stage duration is published any more. A predicted duration we cannot\n# honour is worse than none: the real cost of a stage depends on the selected\n# platforms, the collected history AND the provider's latency, so every forecast\n# was wrong for someone and a healthy long run read as broken (field report\n# 2026-07-20 — the GUI announced \"本阶段通常约 3 分钟\" / \"约 5 分钟\" while the\n# run legitimately took 30-45+ minutes). The GUI now renders observed facts\n# only: elapsed time in the stage plus real ``progress`` counts, and an\n# indeterminate bar where no real count exists. Do NOT reintroduce an\n# ``eta_seconds`` field here — the CLI keeps its own console-only estimate in\n# ``cli._run_with_progress``, which is a separate surface that prints elapsed\n# alongside it and explicitly flips to \"已超预估、仍在处理\".\ndef _initial_stages() -> list[dict[str, Any]]:\n    return [\n        {\n            \"n\": n,\n            \"label\": _STAGE_LABELS[n],\n            \"status\": \"pending\",\n            \"reason\": None,\n        }\n        for n in range(1, _TOTAL_STAGES + 1)\n    ]\n\n\ndef _utcnow_iso() -> str:\n    return datetime.now(UTC).strftime(\"%Y-%m-%d %H:%M:%S\")\n\n\nclass InitCoordinator:\n    \"\"\"Lifecycle owner for one guided-init run at a time.\"\"\"\n\n    def __init__(self, ctx: Any) -> None:\n        self._ctx = ctx\n        self._current_task: asyncio.Task[Any] | None = None\n        self._current_run_id: str | None = None\n        self._reconcile_tasks: set[asyncio.Task[None]] = set()\n        self._enqueued_task_ids: set[str] = set()\n        # Serializes status writes + event publishes so liveness heartbeats and\n        # substantive stage progress cannot interleave / reorder ``sequence``.\n        self._write_lock = asyncio.Lock()\n        self._seq = 0\n\n    # ── lazy component access (survives rebuild) ───────────────────────────\n    @property\n    def _db(self) -> Any:\n        return self._ctx.database\n\n    @property\n    def _event_hub(self) -> Any:\n        return getattr(self._ctx, \"event_hub\", None)\n\n    # ── boot / liveness ────────────────────────────────────────────────────\n    def reconcile_on_boot(self) -> int:\n        \"\"\"Fail stale starting/running runs left by a crash. Returns count.\"\"\"\n        db = self._db\n        if db is None:\n            return 0\n        return int(db.reconcile_init_runs_on_boot())\n\n    def init_active(self) -> bool:\n        run = self._db.get_latest_init_run()\n        return bool(run and run[\"status\"] in _ACTIVE)\n\n    # ── start / reset (TOCTOU lives in the DB CAS; E2 does cheap pre-checks) ─\n    def try_start(self, run_id: str) -> bool:\n        \"\"\"Reserve a new run (single-flight). Seeds the stage list on success.\"\"\"\n        if not self._db.try_reserve_init_starting(run_id):\n            return False\n        self._enqueued_task_ids = set()\n        self._current_task = None\n        self._current_run_id = run_id\n        self._seq = 0\n        self._db.update_init_run(\n            run_id, stages_json=json.dumps(_initial_stages(), ensure_ascii=False)\n        )\n        return True\n\n    def reset_to_idle(self, run_id: str, *, reason: str | None = None) -> None:\n        \"\"\"Roll a reserved-but-not-launched run back (E2 pre-flight reject).\"\"\"\n        self._db.update_init_run(run_id, status=\"idle\", error_reason=reason)\n        if self._current_run_id == run_id and (\n            self._current_task is None or self._current_task.done()\n        ):\n            self._current_task = None\n            self._current_run_id = None\n            self._enqueued_task_ids.clear()\n\n    # ── bootstrap task ownership (consulted by writer-gating, D1) ──────────\n    def register_enqueued_task(self, run_id: str, task_id: str) -> None:\n        if self._current_run_id == run_id and self.init_active():\n            self._enqueued_task_ids.add(str(task_id))\n\n    def is_owned_bootstrap_task(self, task_id: str) -> bool:\n        return self.init_active() and str(task_id) in self._enqueued_task_ids\n\n    def owned_task_ids(self) -> set[str]:\n        \"\"\"Bootstrap task ids enqueued by the active run (empty if idle).\n\n        ``next-task`` consults this so the extension is only handed init's own\n        bootstrap work while a run is active — never a stale pending task that\n        would otherwise starve the run's collectors (gui-init review).\"\"\"\n        if not self.init_active():\n            return set()\n        return set(self._enqueued_task_ids)\n\n    # ── background task handle (for cancel) ────────────────────────────────\n    def attach_task(self, run_id: str, task: asyncio.Task[Any]) -> None:\n        self._current_run_id = run_id\n        self._current_task = task\n\n        def _on_done(_task: asyncio.Task[Any]) -> None:\n            # The normal wrapper persists completed/failed/cancelled before it\n            # exits. If that terminal write itself failed, the DB would still\n            # say running while the only owning task is already gone. Recheck\n            # after every task exit and close that lease deterministically.\n            async def _recover() -> None:\n                try:\n                    await self.reconcile_orphaned_run(run_id, force_task_done=True)\n                except Exception:\n                    logger.exception(\"failed to reconcile finished init task %s\", run_id)\n                finally:\n                    if self._current_run_id == run_id and self._current_task is _task:\n                        self._current_task = None\n                        self._current_run_id = None\n                        self._enqueued_task_ids.clear()\n\n            recovery = asyncio.create_task(_recover())\n            self._reconcile_tasks.add(recovery)\n            recovery.add_done_callback(self._reconcile_tasks.discard)\n\n        task.add_done_callback(_on_done)\n\n    async def cancel_current_run(self, run_id: str) -> bool:\n        \"\"\"Request cancellation of the running task. The wrapper's ``finally``\n        persists the ``cancelled`` status (single-writer; spec §5f).\"\"\"\n        task = self._current_task\n        if self._current_run_id != run_id or task is None or task.done():\n            return False\n        task.cancel()\n        return True\n\n    async def reconcile_orphaned_run(\n        self,\n        run_id: str | None = None,\n        *,\n        max_heartbeat_age_seconds: float = _ORPHAN_HEARTBEAT_SECONDS,\n        force_task_done: bool = False,\n    ) -> bool:\n        \"\"\"Fail an active row whose owning task has disappeared.\n\n        A newly-reserved ``starting`` row intentionally has a short window\n        before :meth:`attach_task`, so a missing handle is only considered an\n        orphan once its heartbeat lease expires. A known completed task is\n        definitive and is reconciled immediately. Returns whether a row was\n        changed.\n        \"\"\"\n        async with self._write_lock:\n            run = self._db.get_latest_init_run()\n            if run is None or run.get(\"status\") not in _ACTIVE:\n                return False\n            active_run_id = str(run.get(\"run_id\") or \"\")\n            if run_id is not None and active_run_id != str(run_id):\n                return False\n\n            owns_task = self._current_run_id == active_run_id\n            task = self._current_task if owns_task else None\n            task_done = bool(task is not None and task.done())\n            heartbeat_age = _timestamp_age_seconds(run.get(\"updated_at\"))\n            lease_expired_without_owner = task is None and heartbeat_age >= max(\n                0.0, float(max_heartbeat_age_seconds)\n            )\n            if not task_done and not lease_expired_without_owner:\n                return False\n            if force_task_done and task is not None and not task_done:\n                return False\n\n            stages = json.loads(run[\"stages_json\"]) if run.get(\"stages_json\") else _initial_stages()\n            for stage in stages:\n                if stage.get(\"status\") in (\"running\", \"pending\"):\n                    stage[\"status\"] = \"failed\"\n                    stage[\"reason\"] = \"interrupted\"\n                    stage.pop(\"progress\", None)\n            self._seq = max(self._seq, int(run.get(\"sequence\") or 0)) + 1\n            now = _utcnow_iso()\n            self._db.update_init_run(\n                active_run_id,\n                status=\"failed\",\n                stages_json=json.dumps(stages, ensure_ascii=False),\n                error_reason=\"interrupted\",\n                error_detail=\"初始化后台任务已结束，但未能写入终态；已自动释放运行锁。\",\n                sequence=self._seq,\n                progress_sequence=self._seq,\n                progress_at=now,\n                finished_at=now,\n            )\n            if self._event_hub is not None:\n                with contextlib.suppress(Exception):\n                    await self._event_hub.publish(\n                        {\n                            \"type\": \"init_failed\",\n                            \"run_id\": active_run_id,\n                            \"sequence\": self._seq,\n                            \"stage\": _current_stage(stages),\n                            \"total\": _TOTAL_STAGES,\n                            \"reason\": \"interrupted\",\n                        }\n                    )\n            if owns_task:\n                self._current_task = None\n                self._current_run_id = None\n                self._enqueued_task_ids.clear()\n            return True\n\n    # ── single status writer ───────────────────────────────────────────────\n    async def _write(\n        self,\n        run_id: str,\n        *,\n        status: str | None = None,\n        stage: int | None = None,\n        stage_status: str | None = None,\n        stage_reason: str | None = None,\n        partial_success: bool | None = None,\n        error_reason: str | None = None,\n        error_detail: str | None = None,\n        finished: bool = False,\n        stage_progress: dict[str, Any] | None = None,\n        event_type: str | None = None,\n        event_extra: dict[str, Any] | None = None,\n        substantive: bool = True,\n    ) -> int:\n        async with self._write_lock:\n            run = self._db.get_latest_init_run()\n            # A terminal run can be followed by a new reservation before every\n            # old callback/heartbeat has unwound. Never let a late writer build\n            # its stage payload from the new run's row or publish a stale event.\n            if run is None or str(run.get(\"run_id\") or \"\") != str(run_id):\n                return int(run.get(\"sequence\") or self._seq) if run is not None else self._seq\n            # The first terminal write owns the final snapshot. A provider task\n            # can finish just after its sibling failed (or can briefly ignore\n            # cancellation); its late heartbeat/progress must not mutate the\n            # diagnostic timeline or replace failure with completion.\n            if str(run.get(\"status\") or \"\") not in _ACTIVE:\n                return int(run.get(\"sequence\") or self._seq)\n            stages = json.loads(run[\"stages_json\"]) if run.get(\"stages_json\") else _initial_stages()\n            # Defense in depth for the central initialization invariant: stage\n            # 4 may never observe a draft/missing profile, even if a future\n            # caller accidentally regresses the pipeline ordering.\n            if stage == 4 and stage_status == \"running\":\n                profile_stage = next((s for s in stages if int(s.get(\"n\", 0)) == 3), None)\n                if profile_stage is None or profile_stage.get(\"status\") not in (\"ok\", \"warning\"):\n                    raise RuntimeError(\n                        \"cannot start init stage 4 before the full profile stage is committed\"\n                    )\n            if stage is not None and stage_status is not None:\n                for s in stages:\n                    if s[\"n\"] == stage:\n                        s[\"status\"] = stage_status\n                        s[\"reason\"] = stage_reason\n                        # A stage leaving \"running\" (ok / warning / failed) has\n                        # no live sub-progress anymore — drop it so the GUI\n                        # doesn't render a stale \"第 3/8 批\" on a done stage.\n                        if stage_status != \"running\":\n                            s.pop(\"progress\", None)\n            # A pure sub-progress write attaches the {done,total,note} payload\n            # to the (still-running) stage without touching its status.\n            if stage is not None and stage_progress is not None:\n                for s in stages:\n                    if s[\"n\"] == stage:\n                        s[\"progress\"] = stage_progress\n            # On a terminal failure/cancel, downgrade any still-\"running\" or\n            # \"pending\" stage so status consumers (and the extension checklist,\n            # which keys off stage status) don't show a non-terminal timeline\n            # for a finished run (gui-init review).\n            if status in (\"failed\", \"cancelled\"):\n                for s in stages:\n                    if s[\"status\"] in (\"running\", \"pending\"):\n                        s[\"status\"] = status\n                        s.pop(\"progress\", None)\n                        if s.get(\"reason\") is None:\n                            s[\"reason\"] = error_reason\n            self._seq = max(self._seq, int(run.get(\"sequence\") or 0) if run else 0) + 1\n            fields: dict[str, Any] = {\n                \"sequence\": self._seq,\n                \"stages_json\": json.dumps(stages, ensure_ascii=False),\n            }\n            if substantive:\n                fields[\"progress_sequence\"] = self._seq\n                fields[\"progress_at\"] = _utcnow_iso()\n            if status is not None:\n                fields[\"status\"] = status\n            if stage is not None:\n                fields[\"stage\"] = stage\n            if partial_success is not None:\n                fields[\"partial_success\"] = 1 if partial_success else 0\n            if error_reason is not None:\n                fields[\"error_reason\"] = error_reason\n            if error_detail is not None:\n                fields[\"error_detail\"] = error_detail\n            if finished:\n                fields[\"finished_at\"] = _utcnow_iso()\n            self._db.update_init_run(run_id, **fields)\n\n            if event_type and self._event_hub is not None:\n                event: dict[str, Any] = {\n                    \"type\": event_type,\n                    \"run_id\": run_id,\n                    \"sequence\": self._seq,\n                    \"stage\": stage if stage is not None else _current_stage(stages),\n                    \"total\": _TOTAL_STAGES,\n                }\n                if event_extra:\n                    event.update(event_extra)\n                with contextlib.suppress(Exception):\n                    await self._event_hub.publish(event)\n            return self._seq\n\n    async def mark_running(self, run_id: str) -> None:\n        await self._write(run_id, status=\"running\")\n\n    async def stage_started(self, run_id: str, stage: int) -> None:\n        await self._write(\n            run_id,\n            status=\"running\",\n            stage=stage,\n            stage_status=\"running\",\n            event_type=\"init_progress\",\n        )\n\n    async def stage_done(\n        self, run_id: str, stage: int, *, status: str = \"ok\", reason: str | None = None\n    ) -> None:\n        await self._write(\n            run_id,\n            stage=stage,\n            stage_status=status,\n            stage_reason=reason,\n            event_type=\"init_progress\",\n        )\n\n    async def stage_progress(\n        self,\n        run_id: str,\n        stage: int,\n        *,\n        done: int = 0,\n        total: int = 0,\n        note: str | None = None,\n        mode: str = \"determinate\",\n        elapsed_seconds: int | None = None,\n        max_seconds: int | None = None,\n        substantive: bool = True,\n    ) -> None:\n        \"\"\"Report fine-grained progress within a running stage (spec Phase 0).\n\n        ``done`` is clamped to ``0 ≤ done ≤ total``; a non-positive ``total`` is\n        ignored (no write, no event) so a producer that hasn't sized its work\n        yet can't stamp a meaningless 0/0. Publishes ``init_progress`` carrying\n        the payload so SSE-driven pages advance without waiting for the poll.\n        \"\"\"\n        normalized_mode = \"indeterminate\" if mode == \"indeterminate\" else \"determinate\"\n        if normalized_mode == \"determinate\" and total <= 0:\n            return\n        safe_total = max(0, int(total))\n        clamped = max(0, min(int(done), safe_total)) if safe_total else 0\n        payload: dict[str, Any] = {\n            \"done\": clamped,\n            \"total\": safe_total,\n            \"note\": note,\n            \"mode\": normalized_mode,\n        }\n        if elapsed_seconds is not None:\n            payload[\"elapsed_seconds\"] = max(0, int(elapsed_seconds))\n        if max_seconds is not None:\n            payload[\"max_seconds\"] = max(0, int(max_seconds))\n        await self._write(\n            run_id,\n            stage=stage,\n            stage_progress=payload,\n            event_type=\"init_progress\",\n            event_extra={\"progress\": payload},\n            substantive=substantive,\n        )\n\n    async def touch(self, run_id: str) -> None:\n        \"\"\"Liveness heartbeat: bump ``sequence`` + ``updated_at`` only.\n\n        It does not advance ``progress_sequence`` / ``progress_at`` and does not\n        publish an event. Front ends can therefore distinguish \"backend owner is\n        alive\" from \"the current operation made useful progress\" without\n        flooding SSE with content-free frames.\n        \"\"\"\n        await self._write(run_id, substantive=False)\n\n    async def complete(\n        self,\n        run_id: str,\n        *,\n        partial_success: bool = False,\n        reason: str | None = None,\n        detail: str | None = None,\n    ) -> None:\n        \"\"\"Finish a run, retaining a diagnosable partial-success reason.\n\n        A discovery timeout is deliberately not a hard failure once the profile\n        exists. ``reason`` / ``detail`` let status consumers explain that\n        degraded terminal state instead of presenting it as a silent success.\n        \"\"\"\n        await self._write(\n            run_id,\n            status=\"completed\",\n            partial_success=partial_success,\n            error_reason=reason,\n            error_detail=detail,\n            finished=True,\n            event_type=\"init_completed\",\n            event_extra={\n                \"partial_success\": partial_success,\n                \"reason\": reason or \"none\",\n                \"detail\": detail or \"\",\n            },\n        )\n\n    async def fail(self, run_id: str, reason: str, detail: str | None = None) -> None:\n        \"\"\"Terminal failure. ``detail`` carries the human-readable specifics\n        (GuidedInitError message / exception summary) so status consumers can\n        show WHY instead of only the generic reason code.\"\"\"\n        await self._write(\n            run_id,\n            status=\"failed\",\n            error_reason=reason,\n            error_detail=(detail or \"\").strip() or None,\n            finished=True,\n            event_type=\"init_failed\",\n            event_extra={\"reason\": reason},\n        )\n\n    async def cancel(self, run_id: str, reason: str = \"cancelled\") -> None:\n        await self._write(\n            run_id,\n            status=\"cancelled\",\n            error_reason=reason,\n            finished=True,\n            event_type=\"init_failed\",\n            event_extra={\"reason\": reason},\n        )\n\n    # ── status read (run-derived part; E1 adds prereqs/can_manage) ─────────\n    def get_status(self) -> dict[str, Any]:\n        run = self._db.get_latest_init_run()\n        if run is None:\n            return {\n                \"running\": False,\n                \"run_id\": None,\n                \"sequence\": 0,\n                \"current_stage\": 0,\n                \"total_stages\": _TOTAL_STAGES,\n                \"stages\": _initial_stages(),\n                \"partial_success\": False,\n                \"status\": \"idle\",\n                \"reason\": \"none\",\n                \"detail\": \"\",\n                \"last_activity\": \"\",\n                \"last_heartbeat_at\": \"\",\n                \"last_progress_at\": \"\",\n                \"progress_sequence\": 0,\n            }\n        stages = json.loads(run[\"stages_json\"]) if run.get(\"stages_json\") else _initial_stages()\n        return {\n            \"running\": run[\"status\"] in _ACTIVE,\n            \"run_id\": run[\"run_id\"],\n            \"sequence\": run[\"sequence\"],\n            \"current_stage\": _current_stage(stages),\n            \"total_stages\": _TOTAL_STAGES,\n            \"stages\": stages,\n            \"partial_success\": bool(run[\"partial_success\"]),\n            \"status\": run[\"status\"],\n            \"reason\": run[\"error_reason\"] or \"none\",\n            \"detail\": str(run.get(\"error_detail\") or \"\"),\n            # ``last_activity`` stays as a compatibility alias for old clients.\n            # New clients separately render backend liveness and useful progress.\n            \"last_activity\": str(run.get(\"updated_at\") or \"\"),\n            \"last_heartbeat_at\": str(run.get(\"updated_at\") or \"\"),\n            \"last_progress_at\": str(run.get(\"progress_at\") or run.get(\"updated_at\") or \"\"),\n            \"progress_sequence\": int(run.get(\"progress_sequence\") or 0),\n        }\n\n\ndef _timestamp_age_seconds(value: Any) -> float:\n    \"\"\"Best-effort age for SQLite/ISO timestamps; malformed means expired.\"\"\"\n    raw = str(value or \"\").strip()\n    if not raw:\n        return float(\"inf\")\n    try:\n        parsed = datetime.fromisoformat(raw.replace(\"Z\", \"+00:00\"))\n        if parsed.tzinfo is None:\n            parsed = parsed.replace(tzinfo=UTC)\n        return max(0.0, (datetime.now(UTC) - parsed.astimezone(UTC)).total_seconds())\n    except (TypeError, ValueError):\n        return float(\"inf\")\n\n\ndef _current_stage(stages: Sequence[dict[str, Any]]) -> int:\n    \"\"\"Lowest still-running stage; else the highest completed; else 0 (spec §5e).\"\"\"\n    running = [int(s[\"n\"]) for s in stages if s[\"status\"] == \"running\"]\n    if running:\n        return min(running)\n    # A terminal write marks the failed/cancelled stage and every later\n    # pending stage terminal so clients never render a live-looking timeline.\n    # The first such stage is the actual stop point; taking the highest would\n    # misleadingly report stage 4 when stage 2 was cancelled.\n    terminal = [int(s[\"n\"]) for s in stages if s[\"status\"] in (\"failed\", \"cancelled\")]\n    if terminal:\n        return min(terminal)\n    done = [int(s[\"n\"]) for s in stages if s[\"status\"] in (\"ok\", \"warning\", \"failed\")]\n    return max(done) if done else 0\n"
    },
    {
      "path": "src/openbiliclaw/llm/sponsored_provider.py",
      "content": "\"\"\"IPC client for the closed-source ``obc-sponsored-runtime`` child process.\n\nThe provider speaks a deliberately narrow protocol: spawn the runtime, say\nhello, execute one contract-validated task at a time, and map runtime error\ncodes to typed exceptions. It never sees the sponsored API key and never\nopens a TCP port of its own.\n\"\"\"\n\nfrom __future__ import annotations\n\nimport asyncio\nimport json\nimport logging\nimport math\nimport os\nimport re\nimport shlex\nimport uuid\nfrom collections.abc import AsyncGenerator, Mapping, Sequence\nfrom contextlib import asynccontextmanager, suppress\nfrom typing import TYPE_CHECKING, Any\n\nfrom openbiliclaw import __version__\nfrom openbiliclaw.proc import no_window_kwargs\nfrom openbiliclaw.sponsored_runtime_state import (\n    DEFAULT_SPONSORED_REQUEST_TIMEOUT_SECONDS,\n    SPONSORED_EMBEDDING_TIMEOUT_SECONDS,\n)\n\nfrom .base import LLMResponse, LLMStreamChunk\nfrom .concurrency import is_interactive_caller\nfrom .sponsored_errors import (\n    SponsoredAuthError,\n    SponsoredContractMismatchError,\n    SponsoredError,\n    SponsoredPolicyInvalidError,\n    SponsoredProtocolError,\n    SponsoredRateLimitedError,\n    SponsoredRequestTooLargeError,\n    SponsoredStartupBusyError,\n    SponsoredUnavailableError,\n    SponsoredUnsupportedTaskError,\n    error_from_payload,\n    is_free_model_fallback_allowed,\n)\nfrom .sponsored_protocol import (\n    PROTOCOL_VERSION,\n    encode_frame,\n    read_frame_async,\n    write_frame_async,\n)\nfrom .sponsored_tasks import DEFAULT_SPONSORED_REGISTRY\n\nif TYPE_CHECKING:\n    from .sponsored_contracts import SponsoredContractRegistry, SponsoredTaskContract\n\nlogger = logging.getLogger(__name__)\n\nDEFAULT_REQUEST_TIMEOUT_SECONDS = DEFAULT_SPONSORED_REQUEST_TIMEOUT_SECONDS\nDEFAULT_HANDSHAKE_TIMEOUT_SECONDS = 10.0\n# Nov 8: 30s rejected the already-observed 27–85s cold first responses.\n# Allow queued/cold chat five minutes within the configured overall deadline.\n# Explicit thinking keeps the full request budget. Recheck after model swaps.\nINTERACTIVE_FIRST_DELTA_TIMEOUT_SECONDS = 300.0\n# Rust quota.rs uses a 60s sliding RPM window shared by chat and embeddings.\n# A 1,055-event live initialization filled it during the post-profile embedding\n# burst (2026-11-08). Wait once, within the original operation deadline; never\n# bypass the signed cap or replay an upstream request / visible stream.\nLOCAL_RATE_WINDOW_SECONDS = 60.0\n_STDERR_TAIL_BYTES = 4096\n\nSPONSORED_ENABLED_ENV = \"OPENBILICLAW_SPONSORED_ENABLED\"\nSPONSORED_RUNTIME_ENV = \"OPENBILICLAW_SPONSORED_RUNTIME\"\n_TRUTHY_ENV_VALUES = frozenset({\"1\", \"true\", \"yes\", \"on\"})\n\n\ndef _is_local_rate_rejection(frame: Mapping[str, Any]) -> bool:\n    error = frame.get(\"error\")\n    if frame.get(\"ok\") is not False or not isinstance(error, Mapping):\n        return False\n    mapped = error_from_payload(error)\n    return isinstance(mapped, SponsoredRateLimitedError) and mapped.is_local\n\n\nclass SponsoredProvider:\n    \"\"\"Execute Sponsored tasks through a policy-validating local runtime.\n\n    One provider instance owns one long-lived child process. Requests are\n    serialized per process; callers that need concurrency should run several\n    provider instances, each with its own child.\n    \"\"\"\n\n    def __init__(\n        self,\n        runtime_command: Sequence[str],\n        *,\n        registry: SponsoredContractRegistry = DEFAULT_SPONSORED_REGISTRY,\n        request_timeout: float = DEFAULT_REQUEST_TIMEOUT_SECONDS,\n        handshake_timeout: float = DEFAULT_HANDSHAKE_TIMEOUT_SECONDS,\n        env: Mapping[str, str] | None = None,\n        model: str | None = None,\n        fallback_to_other_free_model: bool = True,\n    ) -> None:\n        if not runtime_command:\n            raise ValueError(\"runtime_command must not be empty\")\n        from .sponsored_profiles import CHAT_MODELS\n\n        if model is not None and model not in CHAT_MODELS:\n            raise ValueError(\"unsupported free chat model\")\n        if any(not math.isfinite(t) or t <= 0 for t in (request_timeout, handshake_timeout)):\n            raise ValueError(\"timeouts must be positive\")\n        self._runtime_command = tuple(str(part) for part in runtime_command)\n        self._registry = registry\n        self._chat_model = model\n        self._free_fallback = fallback_to_other_free_model\n        self._streaming = False\n        self._request_timeouts = False\n        self._request_timeout = float(request_timeout)\n        self._handshake_timeout = float(handshake_timeout)\n        self._extra_env = dict(env) if env is not None else None\n        self._process: asyncio.subprocess.Process | None = None\n        self._stderr_task: asyncio.Task[None] | None = None\n        self._stderr_tail = bytearray()\n        self._start_lock = asyncio.Lock()\n        self._request_lock = asyncio.Lock()\n        self._policy_version = 0\n\n    @property\n    def policy_version(self) -> int:\n        return self._policy_version\n\n    @property\n    def runtime_running(self) -> bool:\n        return self._process is not None and self._process.returncode is None\n\n    def _operation_timeout(self, operation: str) -> float:\n        \"\"\"Keep embedding latency bounded independently of long text jobs.\"\"\"\n        return (\n            min(self._request_timeout, SPONSORED_EMBEDDING_TIMEOUT_SECONDS)\n            if operation.startswith(\"embedding_\")\n            else self._request_timeout\n        )\n\n    def _transport_budget(self, seconds: float) -> dict[str, int]:\n        # Old signed SDKs reject unknown frame fields; negotiate the extension.\n        return (\n            {\"timeout_ms\": max(1, min(3_600_000, int(seconds * 1000)))}\n            if self._request_timeouts\n            else {}\n        )\n\n    async def execute_task(\n        self,\n        *,\n        caller: str = \"\",\n        task_id: str = \"\",\n        contract_version: int | None = None,\n        user_payload: Mapping[str, Any],\n        user_text: str | None = None,\n        system_prompt: str | None = None,\n    ) -> LLMResponse:\n        \"\"\"Choose only signed model variants; never fall through to a paid provider.\"\"\"\n        contracts = self._candidate_contracts(caller, task_id, contract_version)\n        for index, contract in enumerate(contracts):\n            try:\n                payload = self._bounded_operation_payload(contract, user_payload)\n                self._check_context(contract, payload)\n                response = await self._execute_task_once(\n                    task_id=contract.task_id,\n                    contract_version=contract.contract_version,\n                    user_payload=payload,\n                    user_text=user_text,\n                    system_prompt=system_prompt,\n                )\n                response.raw = dict(response.raw or {})\n                response.raw[\"requested_model\"] = contracts[0].model\n                response.raw[\"free_model_fallback\"] = index > 0\n                return response\n            except SponsoredError as exc:\n                if index + 1 == len(contracts) or not is_free_model_fallback_allowed(exc):\n                    raise\n                logger.warning(\"free model fallback: %s (%s)\", contract.model, exc.code)\n        raise SponsoredUnavailableError(\"no signed free model is available\")\n\n    @property\n    def supports_image_input(self) -> bool:\n        return self._registry.get(\"llm.vision\") is not None\n\n    def _candidate_contracts(\n        self, caller: str, task_id: str, version: int | None\n    ) -> list[SponsoredTaskContract]:\n        from .sponsored_profiles import ALTERNATE_CHAT_MODEL, ALTERNATE_TASK_SUFFIX\n\n        contract = self._resolve_contract(caller=caller, task_id=task_id, contract_version=version)\n        alternate = self._registry.get(contract.task_id + ALTERNATE_TASK_SUFFIX)\n        if alternate is None:\n            return [contract]\n        candidates = (\n            [alternate, contract]\n            if self._chat_model == ALTERNATE_CHAT_MODEL\n            else [contract, alternate]\n        )\n        return candidates if self._free_fallback else candidates[:1]\n\n    @staticmethod\n    def _bounded_operation_payload(\n        contract: SponsoredTaskContract, payload: Mapping[str, Any]\n    ) -> Mapping[str, Any]:\n        \"\"\"Keep implicit free-model thinking inside the normal task deadline.\n\n        Live full-profile calls exceeded 180s with the upstream's unspecified\n        thinking default. 8B structured tasks retain a 1024-token reasoning\n        budget when the output allowance leaves room for an answer; shorter\n        requests, 4B and conversational/tool replies default to no thinking.\n        Explicit caller choices, including high/max and disabled, stay intact.\n        Resolve after choosing the contract so free fallback uses its own model.\n        \"\"\"\n        from .sponsored_profiles import CHAT_MODELS, DEFAULT_CHAT_MODEL\n\n        if (\n            contract.model not in CHAT_MODELS\n            or contract.operation not in {\"structured\", \"text\", \"tools\", \"vision\"}\n            or payload.get(\"reasoning_effort\") is not None\n        ):\n            return payload\n        max_tokens = payload.get(\"max_tokens\", 0)\n        effort = (\n            \"low\"\n            if (\n                contract.model == DEFAULT_CHAT_MODEL\n                and contract.operation == \"structured\"\n                and isinstance(max_tokens, int)\n                and max_tokens >= 2048\n            )\n            else \"\"\n        )\n        return {**payload, \"reasoning_effort\": effort}\n\n    @staticmethod\n    def _check_context(contract: SponsoredTaskContract, payload: Mapping[str, Any]) -> None:\n        from .sponsored_profiles import CONTEXT_WINDOWS, EMBEDDING_MODEL, context_input_bound\n\n        window = CONTEXT_WINDOWS.get(contract.model)\n        if window is not None:\n            output = int(payload.get(\"max_tokens\", contract.max_output_tokens))\n            bound = context_input_bound(payload, vision=contract.operation == \"vision\")\n            if bound + output > window:\n                raise SponsoredRequestTooLargeError(\n                    f\"{contract.model} context budget exceeded; split the task or shorten history\",\n                    task_id=contract.task_id,\n                )\n        elif (\n            contract.model == EMBEDDING_MODEL\n            and len(str(payload.get(\"text\", \"\")).encode(\"utf-8\")) > 8192\n        ):\n            raise SponsoredRequestTooLargeError(\"BGE-M3 input exceeds the conservative text budget\")\n\n    async def _execute_task_once(\n        self,\n        *,\n        caller: str = \"\",\n        task_id: str = \"\",\n        contract_version: int | None = None,\n        user_payload: Mapping[str, Any],\n        user_text: str | None = None,\n        system_prompt: str | None = None,\n    ) -> LLMResponse:\n        \"\"\"Run one Sponsored task and return the standardized response.\n\n        Fixed v2 tasks send only structured input. Optional user_text and\n        system_prompt are local drift checks against the legacy builder;\n        neither can override the runtime's signed/fixed renderer.\n        \"\"\"\n\n        contract = self._resolve_contract(\n            caller=caller,\n            task_id=task_id,\n            contract_version=contract_version,\n        )\n        if system_prompt is not None and system_prompt != contract.system_prompt:\n            raise SponsoredContractMismatchError(\n                \"system prompt does not match the sponsored contract\",\n                task_id=contract.task_id,\n            )\n        payload_text = self._serialize_payload(user_payload, contract, user_text)\n\n        async with self._observe_task(contract), self._request_lock:\n            await self._ensure_started()\n            process = self._process\n            if process is None or process.stdin is None or process.stdout is None:\n                raise SponsoredUnavailableError(\"runtime pipes are unavailable\")\n\n            request_id = uuid.uuid4().hex\n            request = {\n                \"type\": \"execute\",\n                \"id\": request_id,\n                \"task_id\": contract.task_id,\n                \"contract_version\": contract.contract_version,\n                \"input\": json.loads(payload_text),\n                **self._transport_budget(self._operation_timeout(contract.operation)),\n            }\n\n            deadline = asyncio.get_running_loop().time() + self._operation_timeout(\n                contract.operation\n            )\n            try:\n                await write_frame_async(process.stdin, request)\n            except (SponsoredError, OSError) as exc:\n                await self._stop_process()\n                raise SponsoredUnavailableError(\n                    \"failed to write to sponsored runtime\",\n                    task_id=contract.task_id,\n                ) from exc\n\n            try:\n                async with asyncio.timeout_at(deadline):\n                    response = await read_frame_async(process.stdout)\n                    if response.get(\"id\") == request_id and _is_local_rate_rejection(response):\n                        logger.info(\"Waiting for sponsored local RPM window before one retry\")\n                        await asyncio.sleep(LOCAL_RATE_WINDOW_SECONDS)\n                        request_id = uuid.uuid4().hex\n                        request = {\n                            **request,\n                            \"id\": request_id,\n                            **self._transport_budget(deadline - asyncio.get_running_loop().time()),\n                        }\n                        await write_frame_async(process.stdin, request)\n                        response = await read_frame_async(process.stdout)\n            except TimeoutError as exc:\n                self._cancel_in_flight(process, request_id)\n                await self._stop_process()\n                raise SponsoredUnavailableError(\n                    \"sponsored runtime timed out\",\n                    task_id=contract.task_id,\n                ) from exc\n            except (SponsoredError, OSError) as exc:\n                await self._stop_process()\n                raise SponsoredUnavailableError(\n                    \"sponsored runtime IPC failed\",\n                    task_id=contract.task_id,\n                ) from exc\n            except asyncio.CancelledError:\n                self._abort_process_sync(process)\n                await self._stop_process()\n                raise\n\n            if response.get(\"id\") != request_id:\n                await self._stop_process()\n                raise SponsoredProtocolError(\n                    \"sponsored runtime returned a mismatched response id\",\n                    task_id=contract.task_id,\n                )\n            if response.get(\"ok\") is not True:\n                error_payload = response.get(\"error\")\n                if not isinstance(error_payload, Mapping):\n                    error_payload = {}\n                raise error_from_payload(error_payload, task_id=contract.task_id)\n\n            return LLMResponse(\n                content=str(response.get(\"content\") or \"\"),\n                model=str(response.get(\"model\") or contract.model),\n                instance_id=\"sponsored\",\n                provider=\"sponsored\",\n                usage=_coerce_usage(response.get(\"usage\")),\n                raw=response,\n            )\n\n    async def complete(\n        self,\n        messages: list[dict[str, Any]],\n        *,\n        temperature: float = 0.7,\n        max_tokens: int = 4096,\n        json_mode: bool = False,\n        reasoning_effort: str | None = None,\n        caller: str = \"\",\n    ) -> LLMResponse:\n        \"\"\"Use fixed SDK operations while preserving the application's full messages.\"\"\"\n        if json_mode and messages and messages[0].get(\"role\") == \"system\":\n            from .prompt_contracts import ensure_json_mode_contract\n\n            messages = [dict(m) for m in messages]\n            if isinstance(messages[0].get(\"content\"), str):\n                messages[0][\"content\"] = ensure_json_mode_contract(messages[0][\"content\"])\n        vision = any(\n            isinstance(m.get(\"content\"), list)\n            and any(isinstance(p, dict) and p.get(\"type\") == \"image_url\" for p in m[\"content\"])\n            for m in messages\n        )\n        operation = (\n            \"vision\"\n            if vision\n            else \"tools\"\n            if caller.endswith(\".tools\")\n            else \"structured\"\n            if json_mode\n            else \"text\"\n        )\n        response = await self.execute_task(\n            task_id=f\"llm.{operation}\",\n            user_payload={\n                \"messages\": messages,\n                \"temperature\": temperature,\n                \"max_tokens\": max_tokens,\n                \"reasoning_effort\": reasoning_effort,\n                \"caller\": caller,\n            },\n        )\n        if json_mode:\n            # The signed upstream format permits arrays. Some free replies\n            # still add a whole Markdown fence (Nov 5 live search repro). Strip\n            # only a complete, strictly valid container; never repair its data.\n            fenced = re.fullmatch(\n                r\"\\s*```(?:json)?\\s*\\n(.*?)\\n```\\s*\",\n                response.content,\n                flags=re.DOTALL | re.IGNORECASE,\n            )\n            if fenced:\n                body = fenced.group(1).strip()\n                try:\n                    parsed = json.loads(body)\n                except json.JSONDecodeError:\n                    pass\n                else:\n                    if isinstance(parsed, (dict, list)):\n                        response.content = body\n        return response\n\n    async def complete_with_tools(\n        self,\n        messages: list[dict[str, Any]],\n        tools: list[dict[str, Any]],\n        *,\n        temperature: float = 0.7,\n        max_tokens: int = 4096,\n        reasoning_effort: str | None = None,\n        caller: str = \"\",\n    ) -> LLMResponse:\n        \"\"\"Adapt the project's tool interface using Qwen's tagged text contract.\n\n        The upstream sponsor model need not support native HTTP tool fields.\n        Tool schemas and results remain prompt data; only Core executes tools.\n        \"\"\"\n        from .sponsored_tools import parse_tool_calls, split_tool_content\n\n        canonical, names = self._tool_messages(messages, tools)\n        payload = {\n            \"messages\": canonical,\n            \"temperature\": temperature,\n            \"max_tokens\": max_tokens,\n            \"reasoning_effort\": reasoning_effort,\n            \"caller\": caller,\n        }\n        response = await self.execute_task(task_id=\"llm.tools\", user_payload=payload)\n        response = await self._repair_tool_json(response, payload, names)\n        calls = parse_tool_calls(response.content, names)\n        if calls:\n            response.tool_calls = calls\n            response.content = split_tool_content(response.content)[0]\n        return response\n\n    async def _repair_tool_json(\n        self, response: LLMResponse, payload: Mapping[str, Any], names: list[str]\n    ) -> LLMResponse:\n        \"\"\"Correct one marked syntax error; literal JSON is never an operation.\"\"\"\n        from .sponsored_tools import InvalidToolActionError, parse_tool_calls, split_tool_content\n\n        if not names or not split_tool_content(response.content)[1]:\n            return response\n        try:\n            parse_tool_calls(response.content, names)\n        except InvalidToolActionError:\n            # Valid JSON naming unknown tools or changing argument types is not\n            # a formatting error; never ask the model to guess another action.\n            raise\n        except SponsoredProtocolError:\n            pass\n        else:\n            return response\n        repaired = await self.execute_task(\n            task_id=\"llm.tools\",\n            user_payload={\n                **payload,\n                \"messages\": [\n                    *payload[\"messages\"],\n                    {\"role\": \"assistant\", \"content\": response.content},\n                    {\n                        \"role\": \"user\",\n                        \"content\": (\n                            \"上一条工具标记或 JSON 语法无效，工具尚未执行。\"\n                            \"只修正格式，保留原工具名和参数含义，不得添加新操作。\"\n                            '每个调用使用 <tool_call>{\"name\":\"工具名\",\"arguments\":{}}</tool_call>，'\n                            \"不要解释、代码围栏或 reply 封套。\"\n                        ),\n                    },\n                ],\n                \"temperature\": 0.0,\n            },\n        )\n        if not parse_tool_calls(repaired.content, names):\n            raise SponsoredProtocolError(\"invalid tool JSON after one format correction\")\n        first_usage, next_usage = response.usage or {}, repaired.usage or {}\n        repaired.usage = {\n            key: first_usage.get(key, 0) + next_usage.get(key, 0)\n            for key in first_usage.keys() | next_usage.keys()\n        }\n        repaired.raw = {**(repaired.raw or {}), \"tool_format_repaired\": True}\n        return repaired\n\n    @staticmethod\n    def _tool_messages(\n        messages: list[dict[str, Any]], tools: list[dict[str, Any]]\n    ) -> tuple[list[dict[str, str]], list[str]]:\n        from .sponsored_tools import tool_messages\n\n        return tool_messages(messages, tools)\n\n    async def stream_complete(\n        self,\n        messages: list[dict[str, Any]],\n        **kwargs: Any,\n    ) -> AsyncGenerator[LLMStreamChunk, None]:\n        \"\"\"Forward Rust SSE deltas; never retry after emitting any answer text.\"\"\"\n        await self._ensure_started()\n        if not self._streaming:\n            response = await self.complete(messages, **kwargs)\n            if response.content:\n                yield LLMStreamChunk(delta=response.content)\n            yield LLMStreamChunk(response=response)\n            return\n        if kwargs.get(\"json_mode\") and messages and messages[0].get(\"role\") == \"system\":\n            from .prompt_contracts import ensure_json_mode_contract\n\n            messages = [dict(m) for m in messages]\n            if isinstance(messages[0].get(\"content\"), str):\n                messages[0][\"content\"] = ensure_json_mode_contract(messages[0][\"content\"])\n        vision = any(\n            isinstance(m.get(\"content\"), list)\n            and any(isinstance(p, dict) and p.get(\"type\") == \"image_url\" for p in m[\"content\"])\n            for m in messages\n        )\n        operation = \"vision\" if vision else \"structured\" if kwargs.get(\"json_mode\") else \"text\"\n        payload = {\n            \"messages\": messages,\n            \"temperature\": kwargs.get(\"temperature\", 0.7),\n            \"max_tokens\": kwargs.get(\"max_tokens\", 4096),\n            \"reasoning_effort\": kwargs.get(\"reasoning_effort\"),\n            \"caller\": kwargs.get(\"caller\", \"\"),\n        }\n        stream = self._stream_operation(operation, payload)\n        try:\n            async for chunk in stream:\n                yield chunk\n        finally:\n            await stream.aclose()\n\n    async def _stream_operation(\n        self, operation: str, payload: Mapping[str, Any]\n    ) -> AsyncGenerator[LLMStreamChunk, None]:\n        # One first-output budget for the logical request, including backoff\n        # and same/free-model retries. A per-attempt timer can double the wait.\n        deadline = None\n        if is_interactive_caller(str(payload.get(\"caller\") or \"\")) and payload.get(\n            \"reasoning_effort\"\n        ) in {None, \"\"}:\n            deadline = asyncio.get_running_loop().time() + min(\n                self._request_timeout, INTERACTIVE_FIRST_DELTA_TIMEOUT_SECONDS\n            )\n        stream = self._stream_operation_attempts(operation, payload, first_deadline=deadline)\n        try:\n            while True:\n                try:\n                    async with asyncio.timeout_at(deadline):\n                        chunk = await anext(stream)\n                except StopAsyncIteration:\n                    return\n                if chunk.delta.strip() or chunk.response is not None:\n                    deadline = None\n                yield chunk\n        except TimeoutError as exc:\n            raise SponsoredUnavailableError(\"sponsored first output timed out\") from exc\n        finally:\n            await stream.aclose()\n\n    async def _stream_operation_attempts(\n        self,\n        operation: str,\n        payload: Mapping[str, Any],\n        *,\n        first_deadline: float | None = None,\n    ) -> AsyncGenerator[LLMStreamChunk, None]:\n        contracts = self._candidate_contracts(\"\", f\"llm.{operation}\", None)\n        emitted = False\n        attempts = 2 if is_interactive_caller(str(payload.get(\"caller\") or \"\")) else 1\n        for index, contract in enumerate(contracts):\n            # Same-model retries share this slice. Reserve an equal portion\n            # for each remaining candidate, within the original total budget.\n            model_deadline = None\n            if first_deadline is not None:\n                now = asyncio.get_running_loop().time()\n                model_deadline = now + (first_deadline - now) / (len(contracts) - index)\n            for attempt in range(attempts):\n                try:\n                    bounded = self._bounded_operation_payload(contract, payload)\n                    self._check_context(contract, bounded)\n                    stream = self._stream_task_once(contract, bounded)\n                    try:\n                        while True:\n                            try:\n                                async with asyncio.timeout_at(model_deadline):\n                                    chunk = await anext(stream)\n                            except StopAsyncIteration:\n                                break\n                            except TimeoutError as exc:\n                                raise SponsoredUnavailableError(\n                                    \"sponsored first output timed out\", task_id=contract.task_id\n                                ) from exc\n                            emitted = emitted or bool(chunk.delta) or chunk.response is not None\n                            if chunk.delta.strip() or chunk.response is not None:\n                                model_deadline = None\n                            if chunk.response is not None:\n                                chunk.response.raw = dict(chunk.response.raw or {})\n                                chunk.response.raw.update(\n                                    requested_model=contracts[0].model,\n                                    free_model_fallback=index > 0,\n                                )\n                            yield chunk\n                    finally:\n                        await stream.aclose()\n                    return\n                except SponsoredError as exc:\n                    if emitted or not is_free_model_fallback_allowed(exc):\n                        raise\n                    remaining = (\n                        model_deadline - asyncio.get_running_loop().time()\n                        if model_deadline is not None\n                        else self._request_timeout\n                    )\n                    if (\n                        attempt + 1 < attempts\n                        and exc.code in {\"UPSTREAM_ERROR\", \"UNAVAILABLE\", \"RATE_LIMITED\"}\n                        and remaining > 0\n                    ):\n                        logger.warning(\"Retrying free stream before any output: %s\", exc.code)\n                        await asyncio.sleep(min(0.25, remaining))\n                        continue\n                    if index + 1 == len(contracts):\n                        raise\n                    logger.warning(\"free stream fallback: %s (%s)\", contract.model, exc.code)\n                    break\n\n    async def _stream_task_once(\n        self, contract: SponsoredTaskContract, payload: Mapping[str, Any]\n    ) -> AsyncGenerator[LLMStreamChunk, None]:\n        payload_text = self._serialize_payload(payload, contract, None)\n        async with self._observe_task(contract), self._request_lock:\n            await self._ensure_started()\n            process = self._process\n            if process is None or process.stdin is None or process.stdout is None:\n                raise SponsoredUnavailableError(\"runtime pipes are unavailable\")\n            request_id = uuid.uuid4().hex\n            request = {\n                \"type\": \"execute_stream\",\n                \"id\": request_id,\n                \"task_id\": contract.task_id,\n                \"contract_version\": contract.contract_version,\n                \"input\": json.loads(payload_text),\n                **self._transport_budget(self._operation_timeout(contract.operation)),\n            }\n            deadline = asyncio.get_running_loop().time() + self._operation_timeout(\n                contract.operation\n            )\n            local_retried = False\n            emitted = False\n            try:\n                async with asyncio.timeout_at(deadline):\n                    await write_frame_async(process.stdin, request)\n                    while True:\n                        frame = await read_frame_async(process.stdout)\n                        if frame.get(\"id\") != request_id:\n                            raise SponsoredProtocolError(\"mismatched stream response id\")\n                        if frame.get(\"type\") == \"delta\":\n                            delta = frame.get(\"content\")\n                            if not isinstance(delta, str):\n                                raise SponsoredProtocolError(\"invalid stream delta\")\n                            emitted = True\n                            yield LLMStreamChunk(delta=delta)\n                            continue\n                        if frame.get(\"type\") != \"result\":\n                            raise SponsoredProtocolError(\"invalid stream terminal\")\n                        if frame.get(\"ok\") is not True:\n                            if (\n                                not emitted\n                                and not local_retried\n                                and _is_local_rate_rejection(frame)\n                            ):\n                                logger.info(\"Waiting for sponsored local RPM window before stream\")\n                                await asyncio.sleep(LOCAL_RATE_WINDOW_SECONDS)\n                                local_retried = True\n                                request_id = uuid.uuid4().hex\n                                request = {\n                                    **request,\n                                    \"id\": request_id,\n                                    **self._transport_budget(\n                                        deadline - asyncio.get_running_loop().time()\n                                    ),\n                                }\n                                await write_frame_async(process.stdin, request)\n                                continue\n                            error = frame.get(\"error\")\n                            if not isinstance(error, Mapping):\n                                raise SponsoredProtocolError(\"invalid stream error\")\n                            raise error_from_payload(error, task_id=contract.task_id)\n                        yield LLMStreamChunk(\n                            response=LLMResponse(\n                                content=str(frame.get(\"content\") or \"\"),\n                                model=str(frame.get(\"model\") or contract.model),\n                                instance_id=\"sponsored\",\n                                provider=\"sponsored\",\n                                usage=_coerce_usage(frame.get(\"usage\")),\n                                raw=frame,\n                            )\n                        )\n                        return\n            except TimeoutError as exc:\n                await self._stop_process()\n                raise SponsoredUnavailableError(\"sponsored stream timed out\") from exc\n            except (asyncio.CancelledError, GeneratorExit):\n                self._abort_process_sync(process)\n                await self._stop_process()\n                raise\n            except (SponsoredError, OSError) as exc:\n                await self._stop_process()\n                if isinstance(exc, SponsoredError):\n                    raise\n                raise SponsoredUnavailableError(\"sponsored stream transport failed\") from exc\n\n    async def stream_complete_with_tools(\n        self,\n        messages: list[dict[str, Any]],\n        tools: list[dict[str, Any]],\n        **kwargs: Any,\n    ) -> AsyncGenerator[LLMStreamChunk, None]:\n        \"\"\"Stream ordinary text/JSON while hiding a marked action suffix.\n\n        Whole marked actions are parsed only after the terminal response.\n        Core owns tool execution; transport never replays a started stream.\n        \"\"\"\n        from .sponsored_tools import ToolStreamPrefix, parse_tool_calls, split_tool_content\n\n        await self._ensure_started()\n        if not self._streaming:\n            response = await self.complete_with_tools(messages, tools, **kwargs)\n            if response.content:\n                yield LLMStreamChunk(delta=response.content)\n            yield LLMStreamChunk(response=response)\n            return\n        canonical, names = self._tool_messages(messages, tools)\n        payload = {\n            \"messages\": canonical,\n            \"temperature\": kwargs.get(\"temperature\", 0.7),\n            \"max_tokens\": kwargs.get(\"max_tokens\", 4096),\n            \"reasoning_effort\": kwargs.get(\"reasoning_effort\"),\n            \"caller\": kwargs.get(\"caller\", \"\"),\n        }\n        prefix = ToolStreamPrefix()\n        visible_emitted = False\n        stream = self._stream_operation(\"tools\", payload)\n        try:\n            async for chunk in stream:\n                if chunk.delta:\n                    visible = prefix.feed(chunk.delta)\n                    if visible:\n                        visible_emitted = True\n                        yield LLMStreamChunk(delta=visible)\n                if chunk.response is not None:\n                    response = chunk.response\n                    if not visible_emitted:\n                        # The terminal frame still owns the serial child's\n                        # request lock until this generator is closed.\n                        await stream.aclose()\n                        response = await self._repair_tool_json(response, payload, names)\n                    calls = parse_tool_calls(response.content, names)\n                    if calls:\n                        response.tool_calls = calls\n                        response.content = split_tool_content(response.content)[0]\n                    else:\n                        pending = prefix.finish()\n                        if pending:\n                            yield LLMStreamChunk(delta=pending)\n                    yield LLMStreamChunk(response=response)\n        finally:\n            await stream.aclose()\n\n    async def embedding(self, value: str, *, image: bool = False) -> list[float]:\n        \"\"\"Return a validated vector in the signed model's fixed embedding space.\"\"\"\n        import math\n\n        task_id = \"llm.embedding_image\" if image else \"llm.embedding_text\"\n        contract = self._resolve_contract(caller=\"\", task_id=task_id, contract_version=3)\n        response = await self.execute_task(\n            task_id=task_id,\n            user_payload={\"image\" if image else \"text\": value},\n        )\n        raw = response.raw or {}\n        vector = raw.get(\"embedding\")\n        if (\n            response.model != contract.model\n            or contract.embedding_dimensions <= 0\n            or not isinstance(vector, list)\n            or len(vector) != contract.embedding_dimensions\n            or any(\n                isinstance(x, bool) or not isinstance(x, (float, int)) or not math.isfinite(x)\n                for x in vector\n            )\n            or not any(vector)\n        ):\n            raise SponsoredProtocolError(\"invalid embedding model/dimension/vector\")\n        return [float(x) for x in vector]\n\n    async def aclose(self) -> None:\n        \"\"\"Terminate the runtime child and release IPC resources.\"\"\"\n\n        async with self._request_lock:\n            await self._stop_process()\n\n    async def __aenter__(self) -> SponsoredProvider:\n        await self._ensure_started()\n        return self\n\n    async def __aexit__(self, *exc_info: object) -> None:\n        await self.aclose()\n\n    def _resolve_contract(\n        self,\n        *,\n        caller: str,\n        task_id: str,\n        contract_version: int | None,\n    ) -> SponsoredTaskContract:\n        by_task = self._registry.get(task_id) if task_id else None\n        by_caller = self._registry.resolve_caller(caller) if caller else None\n        if (\n            (task_id and by_task is None)\n            or (caller and by_caller is None)\n            or (by_task is None and by_caller is None)\n        ):\n            raise SponsoredUnsupportedTaskError(\n                \"task is not present in the sponsored policy\",\n                task_id=task_id or caller,\n            )\n        if by_task is not None and by_caller is not None and by_task is not by_caller:\n            raise SponsoredContractMismatchError(\n                \"caller and task_id resolve to different contracts\",\n                task_id=task_id,\n            )\n        contract = by_task or by_caller\n        assert contract is not None\n        if contract_version is not None and contract_version != contract.contract_version:\n            raise SponsoredUnsupportedTaskError(\n                f\"contract version {contract_version} is not supported\",\n                task_id=contract.task_id,\n            )\n        return contract\n\n    @staticmethod\n    def _serialize_payload(\n        payload: Mapping[str, Any],\n        contract: SponsoredTaskContract,\n        user_text: str | None = None,\n    ) -> str:\n        from .consolidation_prompt import render_consolidation_user\n        from .sponsored_tasks import validate_task_input\n\n        if contract.operation != \"consolidation\":\n            from .sponsored_operations import validate_operation_input\n\n            try:\n                data = dict(payload)\n                text = json.dumps(data, ensure_ascii=False, separators=(\",\", \":\"), allow_nan=False)\n                if len(text.encode()) > contract.max_input_bytes:\n                    raise SponsoredRequestTooLargeError(\"SDK input exceeds signed ceiling\")\n                validate_operation_input(\n                    data, contract.operation, max_tokens=contract.max_output_tokens\n                )\n                return text\n            except (TypeError, ValueError, KeyError) as exc:\n                raise SponsoredContractMismatchError(\"invalid fixed SDK operation input\") from exc\n        if (\n            contract.task_id not in {\"soul.consolidation\", \"soul.consolidation.qwen35_4b\"}\n            or contract.contract_version != 2\n        ):\n            raise SponsoredUnsupportedTaskError(\n                \"unsupported fixed task/version\", task_id=contract.task_id\n            )\n        try:\n            data = dict(payload)\n            text = json.dumps(\n                data, ensure_ascii=False, separators=(\",\", \":\"), sort_keys=True, allow_nan=False\n            )\n            if len(text.encode(\"utf-8\")) > contract.max_input_bytes:\n                raise SponsoredRequestTooLargeError(\n                    \"task input exceeds budget\", task_id=contract.task_id\n                )\n            # Check the exact JSON representation that crosses the IPC boundary.\n            data = json.loads(text)\n            validate_task_input(data)\n            canonical_user = render_consolidation_user(**data)\n            if len(canonical_user.encode(\"utf-8\")) > contract.max_input_bytes:\n                raise SponsoredRequestTooLargeError(\n                    \"rendered input exceeds budget\", task_id=contract.task_id\n                )\n            if user_text is not None and user_text != canonical_user:\n                raise ValueError(\"caller text differs from the fixed task renderer\")\n        except (TypeError, ValueError, KeyError) as exc:\n            raise SponsoredContractMismatchError(\n                \"invalid fixed task input\", task_id=contract.task_id\n            ) from exc\n        if len(text.encode(\"utf-8\")) > contract.max_input_bytes:\n            raise SponsoredRequestTooLargeError(\n                \"sponsored user payload exceeds the contract input budget\",\n                task_id=contract.task_id,\n            )\n        return text\n\n    @asynccontextmanager\n    async def _observe_task(self, contract: SponsoredTaskContract) -> AsyncGenerator[None, None]:\n        from openbiliclaw.sponsored_status import record_sponsored_outcome\n\n        capability = \"embedding\" if contract.operation == \"embedding_text\" else \"chat\"\n        try:\n            yield\n        except SponsoredError as exc:\n            record_sponsored_outcome(self._runtime_command, capability=capability, code=exc.code)\n            raise\n        else:\n            record_sponsored_outcome(self._runtime_command, capability=capability)\n\n    async def _ensure_started(self) -> None:\n        async with self._start_lock:\n            if self.runtime_running:\n                return\n            await self._stop_process()\n            self._stderr_tail.clear()\n            try:\n                process = await asyncio.create_subprocess_exec(\n                    *self._runtime_command,\n                    stdin=asyncio.subprocess.PIPE,\n                    stdout=asyncio.subprocess.PIPE,\n                    stderr=asyncio.subprocess.PIPE,\n                    env=self._process_env(),\n                    **no_window_kwargs(),\n                )\n            except (OSError, ValueError) as exc:\n                raise SponsoredUnavailableError(\"sponsored runtime is not available\") from exc\n            self._process = process\n            if process.stderr is not None:\n                self._stderr_task = asyncio.create_task(self._drain_stderr(process.stderr))\n            try:\n                await self._handshake(process)\n            except (SponsoredAuthError, SponsoredPolicyInvalidError) as exc:\n                self._record_startup_failure(exc)\n                await self._stop_process()\n                raise\n            except (SponsoredUnavailableError, SponsoredContractMismatchError):\n                await self._stop_process()\n                raise\n            except SponsoredError as exc:\n                await self._stop_process()\n                if b\"another runtime owns this installation ledger\" in self._stderr_tail:\n                    raise SponsoredStartupBusyError(\"sponsored ledger startup is busy\") from exc\n                # Older signed runtimes report an expired policy before IPC hello.\n                # Match their stable code/prefix, never classify generic startup failures as expiry.\n                if re.search(\n                    rb\"(?m)^obc-sponsored-runtime: (?:ipc error: )?POLICY_INVALID:\",\n                    self._stderr_tail,\n                ):\n                    policy_error = error_from_payload({\"code\": \"POLICY_INVALID\"})\n                    self._record_startup_failure(policy_error)\n                    raise policy_error from exc\n                raise SponsoredUnavailableError(\"sponsored runtime handshake failed\") from exc\n            except TimeoutError as exc:\n                await self._stop_process()\n                raise SponsoredUnavailableError(\"sponsored runtime handshake timed out\") from exc\n\n    def _record_startup_failure(self, error: SponsoredError) -> None:\n        from openbiliclaw.sponsored_status import record_sponsored_outcome\n\n        for capability in (\"chat\", \"embedding\"):\n            record_sponsored_outcome(self._runtime_command, capability=capability, code=error.code)\n\n    async def _handshake(self, process: asyncio.subprocess.Process) -> None:\n        if process.stdin is None or process.stdout is None:\n            raise SponsoredUnavailableError(\"runtime pipes are unavailable\")\n        await write_frame_async(\n            process.stdin,\n            {\n                \"type\": \"hello\",\n                \"protocol\": PROTOCOL_VERSION,\n                \"core\": __version__,\n            },\n        )\n        hello = await asyncio.wait_for(\n            read_frame_async(process.stdout),\n            self._handshake_timeout,\n        )\n        if hello.get(\"ok\") is False and isinstance(hello.get(\"error\"), Mapping):\n            raise error_from_payload(hello[\"error\"])\n        if (\n            hello.get(\"type\") != \"hello\"\n            or hello.get(\"protocol\") != PROTOCOL_VERSION\n            or hello.get(\"ok\") is not True\n        ):\n            raise SponsoredUnavailableError(\n                \"runtime handshake was rejected (protocol/policy mismatch)\"\n            )\n        contracts = hello.get(\"contracts\")\n        self._streaming = hello.get(\"streaming\") is True\n        self._request_timeouts = hello.get(\"request_timeouts\") is True\n        if not isinstance(contracts, Mapping) or any(\n            contracts.get(contract.policy_key) != contract.system_prompt_sha256\n            for contract in self._registry\n        ):\n            raise SponsoredContractMismatchError(\n                \"runtime policy does not match Core prompt contracts\"\n            )\n        try:\n            self._policy_version = int(hello.get(\"policy_version\") or 0)\n        except (TypeError, ValueError):\n            self._policy_version = 0\n\n    async def _stop_process(self) -> None:\n        process, self._process = self._process, None\n        stderr_task, self._stderr_task = self._stderr_task, None\n        if process is not None:\n            if process.stdin is not None:\n                with suppress(Exception):\n                    process.stdin.close()\n            if process.returncode is None:\n                with suppress(ProcessLookupError):\n                    process.terminate()\n                try:\n                    await asyncio.wait_for(process.wait(), 2.0)\n                except (TimeoutError, ProcessLookupError):\n                    with suppress(ProcessLookupError):\n                        process.kill()\n                    with suppress(Exception):\n                        await process.wait()\n        if stderr_task is not None:\n            stderr_task.cancel()\n            with suppress(asyncio.CancelledError):\n                await stderr_task\n\n    async def _drain_stderr(self, stream: asyncio.StreamReader) -> None:\n        try:\n            while True:\n                chunk = await stream.read(4096)\n                if not chunk:\n                    return\n                self._stderr_tail.extend(chunk)\n                if len(self._stderr_tail) > _STDERR_TAIL_BYTES:\n                    del self._stderr_tail[: len(self._stderr_tail) - _STDERR_TAIL_BYTES]\n        except asyncio.CancelledError:\n            raise\n        except Exception:  # pragma: no cover - defensive pipe cleanup\n            logger.debug(\"sponsored runtime stderr drain stopped\", exc_info=True)\n\n    def _cancel_in_flight(\n        self,\n        process: asyncio.subprocess.Process,\n        request_id: str,\n    ) -> None:\n        if process.stdin is None or process.stdin.is_closing():\n            return\n        with suppress(Exception):\n            process.stdin.write(encode_frame({\"type\": \"cancel\", \"id\": request_id}))\n\n    @staticmethod\n    def _abort_process_sync(process: asyncio.subprocess.Process) -> None:\n        with suppress(ProcessLookupError):\n            process.kill()\n\n    def _process_env(self) -> dict[str, str] | None:\n        if self._extra_env is None:\n            return None\n        env = {key: str(value) for key, value in os.environ.items()}\n        env.update({key: str(value) for key, value in self._extra_env.items()})\n        return env\n\n\n_USAGE_KEY_ALIASES = {\n    \"input_tokens\": \"prompt_tokens\",\n    \"output_tokens\": \"completion_tokens\",\n}\n\n\ndef _coerce_usage(raw: Any) -> dict[str, int] | None:\n    \"\"\"Normalize runtime usage keys to the project's provider convention.\"\"\"\n\n    if not isinstance(raw, Mapping):\n        return None\n    usage: dict[str, int] = {}\n    for key, value in raw.items():\n        normalized_key = _USAGE_KEY_ALIASES.get(str(key), str(key))\n        try:\n            usage[normalized_key] = int(value)\n        except (TypeError, ValueError):\n            continue\n    if \"prompt_tokens\" in usage and \"completion_tokens\" in usage and \"total_tokens\" not in usage:\n        usage[\"total_tokens\"] = usage[\"prompt_tokens\"] + usage[\"completion_tokens\"]\n    return usage or None\n\n\ndef build_sponsored_provider_from_env(\n    env: Mapping[str, str] | None = None,\n) -> SponsoredProvider | None:\n    \"\"\"Build a provider from environment variables, default-off.\n\n    This is the bootstrap seam until ``[llm.sponsored]`` config lands. Both\n    variables are required:\n\n    - ``OPENBILICLAW_SPONSORED_ENABLED``: ``1`` / ``true`` / ``yes`` / ``on``;\n    - ``OPENBILICLAW_SPONSORED_RUNTIME``: command line for the runtime binary\n      (or the Python mock runtime during development).\n    \"\"\"\n\n    source = env if env is not None else os.environ\n    enabled = str(source.get(SPONSORED_ENABLED_ENV) or \"\").strip().lower()\n    if enabled not in _TRUTHY_ENV_VALUES:\n        return None\n    command_text = str(source.get(SPONSORED_RUNTIME_ENV) or \"\").strip()\n    if not command_text:\n        return None\n    try:\n        command = shlex.split(command_text)\n    except ValueError:\n        logger.warning(\"invalid %s command line\", SPONSORED_RUNTIME_ENV)\n        return None\n    if not command:\n        return None\n    try:\n        return SponsoredProvider(command)\n    except ValueError:\n        logger.warning(\"could not build sponsored provider from environment\", exc_info=True)\n        return None\n"
