      "path": "src/openbiliclaw/api/auth.py",
      "content": "\"\"\"FastAPI glue for the LAN password gate.\n\nWires the stdlib primitives in :mod:`openbiliclaw.auth_core` to Starlette\nrequests/responses: the auth middleware, the ``/api/auth/*`` routes, cookie and\nCSRF handling, login-failure rate limiting, and startup reconciliation of the\nsession secret and password fingerprint.\n\nSee ``docs/plans/2026-05-30-web-password-auth-design.md``.\n\"\"\"\n\nfrom __future__ import annotations\n\nimport contextlib\nimport logging\nimport os\nimport secrets\nimport time\nfrom collections.abc import Callable\nfrom typing import TYPE_CHECKING, Any\n\nfrom fastapi import FastAPI  # noqa: TC002 - FastAPI needs runtime annotations for routes.\nfrom starlette.requests import (\n    Request,  # noqa: TC002 - FastAPI needs runtime annotations for routes.\n)\nfrom starlette.responses import JSONResponse, Response\n\nfrom openbiliclaw import auth_core\nfrom openbiliclaw.auth_core import COOKIE_NAME, CSRF_HEADER\n\nif TYPE_CHECKING:\n    from starlette.requests import HTTPConnection\n\n    from openbiliclaw.config import ApiAuthConfig\n    from openbiliclaw.storage.database import Database\n\nGateGetter = Callable[[], \"AuthGate\"]\n\nlogger = logging.getLogger(__name__)\n\n_UNSAFE_METHODS = frozenset({\"POST\", \"PUT\", \"PATCH\", \"DELETE\"})\n# GET endpoints with real side effects (claim+lock a source task; bootstrap-write\n# the recommendation history; schedule a pending chat-turn completion). They need\n# CSRF like unsafe methods. The custom `X-OBC-Auth` header is a complete CSRF\n# defense (a credentialed cross-origin request can't set it under\n# allow_origins=[\"*\"]); the SPA sends it on every fetch. img/WS don't hit these\n# paths. See review r2#2 / r3#2.\n_CSRF_GET_EXACT = frozenset(\n    {\n        \"/api/sources/bili/next-task\",\n        \"/api/sources/xhs/next-task\",\n        \"/api/sources/dy/next-task\",\n        \"/api/sources/yt/next-task\",\n        \"/api/sources/x/next-task\",\n        \"/api/sources/zhihu/next-task\",\n        \"/api/sources/reddit/next-task\",\n        \"/api/sources/linuxdo/next-task\",\n        \"/api/sources/v2ex/next-task\",\n        \"/api/sources/weibo/next-task\",\n        \"/api/sources/instagram/next-task\",\n        \"/api/sources/tiktok/next-task\",\n        \"/api/recommendations\",\n    }\n)\n_CSRF_GET_PREFIXES = (\"/api/chat/turns/\",)  # GET /api/chat/turns/{id} resumes a pending turn\n_NEVER_EXPIRE_MAX_AGE = 10 * 365 * 24 * 3600  # ~10 years for \"remember login\"\n\n\ndef _auth_env_overrides() -> list[str]:\n    # When any auth env var is set, auth is env-managed and config-file edits\n    # (incl. the local admin endpoint) won't take effect on restart — see CLI\n    # guard. The canonical var list lives with the config loader so the guard\n    # always matches the real override surface (every field, not just password).\n    from openbiliclaw.config import API_AUTH_ENV_VARS\n\n    return [name for name in API_AUTH_ENV_VARS if (os.environ.get(name) or \"\").strip()]\n\n\ndef _is_mutating_get(path: str) -> bool:\n    return path in _CSRF_GET_EXACT or any(path.startswith(p) for p in _CSRF_GET_PREFIXES)\n\n\nclass _RateLimiter:\n    \"\"\"In-memory per-IP login-failure limiter (resets on restart).\"\"\"\n\n    def __init__(self, *, max_failures: int = 5, window: int = 900, lockout: int = 900) -> None:\n        self._max = max_failures\n        self._window = window\n        self._lockout = lockout\n        self._failures: dict[str, list[float]] = {}\n        self._locked_until: dict[str, float] = {}\n\n    def is_locked(self, key: str, *, now: float | None = None) -> bool:\n        moment = time.time() if now is None else now\n        until = self._locked_until.get(key)\n        if until is None:\n            return False\n        if moment >= until:\n            self._locked_until.pop(key, None)\n            self._failures.pop(key, None)\n            return False\n        return True\n\n    def record_failure(self, key: str, *, now: float | None = None) -> None:\n        moment = time.time() if now is None else now\n        events = [t for t in self._failures.get(key, []) if moment - t < self._window]\n        events.append(moment)\n        self._failures[key] = events\n        if len(events) >= self._max:\n            self._locked_until[key] = moment + self._lockout\n\n    def reset(self, key: str) -> None:\n        self._failures.pop(key, None)\n        self._locked_until.pop(key, None)\n\n\nclass AuthGate:\n    \"\"\"Holds live auth config + database and answers per-request auth questions.\"\"\"\n\n    def __init__(self, auth: ApiAuthConfig, database: Database | None) -> None:\n        self.auth = auth\n        self.database = database\n        self.rate = _RateLimiter()\n        # When startup fingerprint reconciliation fails we cannot guarantee a\n        # password change was revoked, so fail closed for all token auth until a\n        # successful reconcile (loopback still bypasses). See §4.7 / review r1#2.\n        self.reconcile_ok = True\n\n    # ── request introspection ──────────────────────────────────────────\n\n    def resolve_client(self, request: HTTPConnection) -> tuple[str | None, bool]:\n        peer = request.client.host if request.client else \"\"\n        try:\n            xff_values = request.headers.getlist(\"x-forwarded-for\")\n        except AttributeError:  # pragma: no cover - non-starlette headers\n            single = request.headers.get(\"x-forwarded-for\")\n            xff_values = [single] if single else []\n        has_fwd = auth_core.header_present(request.headers)\n        return auth_core.resolve_client_ip(\n            peer,\n            xff_values=xff_values,\n            has_forward_header=has_fwd,\n            trusted_proxies=self.auth.trusted_proxies,\n        )\n\n    def is_trusted_local(self, request: HTTPConnection) -> bool:\n        if not self.auth.trust_loopback:\n            return False\n        client_ip, local = self.resolve_client(request)\n        if not auth_core.is_trusted_local(client_ip, local):\n            return False\n        # A loopback peer is not enough: the user's browser can be driven by a\n        # malicious page to issue cross-origin requests to http://127.0.0.1,\n        # which would otherwise inherit the local bypass (localhost CSRF / DNS\n        # rebinding). Only grant the bypass to non-cross-origin-browser callers:\n        # no Origin (CLI/curl/non-browser), the local web UI itself (same-origin),\n        # a browser extension, or an explicitly allow-listed origin. See review r7.\n        return self._origin_safe_for_local(request)\n\n    def _origin_safe_for_local(self, request: HTTPConnection) -> bool:\n        origin = request.headers.get(\"origin\")\n        if auth_core.is_extension_origin(origin):\n            return True\n        # NOTE: allowed_bearer_origins are deliberately NOT treated as\n        # trusted-local. They are the cross-origin case that authenticates via a\n        # bearer *token*; granting them a no-token local bypass would also hand\n        # them /api/auth/admin (manage the gate) without a session. They still\n        # work via the token path (pick_token). See review r1#1 (admin).\n        # Fetch Metadata: a real browser reveals cross-origin intent even when it\n        # omits Origin (no-cors subresources like\n        # `<img src=\"http://127.0.0.1:8420/api/sources/xhs/next-task\">`). Deny the\n        # local bypass for cross-site / cross-origin-same-site browser requests so a\n        # malicious page can't drive no-Origin loopback state changes. CLI/curl send\n        # no Sec-Fetch-* (unaffected); the extension uses its chrome-extension Origin\n        # branch above. See review r9.\n        if request.headers.get(\"sec-fetch-site\") in (\"cross-site\", \"same-site\"):\n            return False\n        eff = self.effective(request)\n        # DNS-rebinding defense: a rebound browser (Host: evil.example → 127.0.0.1)\n        # connects DIRECTLY, so when the peer itself is loopback the no-Origin /\n        # same-origin exemptions additionally require a canonical loopback Host.\n        # When the client was resolved via a configured trusted proxy (peer is the\n        # proxy, not loopback), the proxy config is the trust anchor and rebinding\n        # doesn't apply, so the Host (the external proxied name) isn't required to\n        # be loopback.\n        peer_host = request.client.host if request.client else None\n        peer_is_loopback = auth_core.is_loopback_host(peer_host)\n        if peer_is_loopback and (eff is None or not auth_core.is_loopback_host(eff[1])):\n            return False\n        if not origin:\n            return True  # CLI/curl/non-browser, or same-origin GET\n        parsed = auth_core.parse_origin(origin)\n        return parsed is not None and auth_core.same_origin(parsed, eff)\n\n    def effective(self, request: HTTPConnection) -> tuple[str, str, int] | None:\n        peer = request.client.host if request.client else \"\"\n        return auth_core.effective_scheme_host(\n            url_scheme=request.url.scheme,\n            host_header=request.headers.get(\"host\"),\n            xf_proto=request.headers.get(\"x-forwarded-proto\"),\n            xf_host=request.headers.get(\"x-forwarded-host\"),\n            peer=peer,\n            trusted_proxies=self.auth.trusted_proxies,\n        )\n\n    def _extract_bearer(self, request: HTTPConnection) -> str | None:\n        authz = request.headers.get(\"authorization\", \"\")\n        if authz.lower().startswith(\"bearer \"):\n            return authz[7:].strip() or None\n        return None\n\n    def pick_token(self, request: HTTPConnection) -> tuple[bool, str | None]:\n        \"\"\"Return ``(used_cookie, token)``.\n\n        Extension origins can use an explicit Bearer session. Non-extension\n        origins use cookie-first then the bearer-origin allow-list. Query\n        tokens are deliberately excluded; their narrow transports handle them\n        explicitly at their call sites.\n        \"\"\"\n        origin = request.headers.get(\"origin\", \"\")\n        bearer = self._extract_bearer(request)\n        if auth_core.is_extension_origin(origin) or (not origin and bearer):\n            # Chrome extension fetches do not consistently send Origin on GET,\n            # even when they send Authorization. Ordinary browser pages cannot\n            # create this shape: adding Authorization triggers CORS and Origin.\n            # Non-browser Bearer clients are valid here as well.\n            return False, bearer\n        # Non-extension path: cookie first, then allowed_bearer_origins\n        cookie = request.cookies.get(COOKIE_NAME)\n        if cookie:\n            return True, cookie\n        if auth_core.origin_allowed_for_bearer(origin, self.auth.allowed_bearer_origins):\n            return False, self._extract_bearer(request)\n        return False, None\n\n    def current_epoch(self) -> int:\n        if self.database is None:\n            raise RuntimeError(\"auth gate has no database\")\n        return self.database.get_auth_epoch()\n\n    def token_valid(self, token: str | None) -> bool:\n        if not token:\n            return False\n        if not self.reconcile_ok:\n            return False  # revocation state unverified → fail closed\n        epoch = self.current_epoch()  # may raise -> caller fails closed\n        return auth_core.verify_token(token, self.auth.session_secret, current_epoch=epoch)\n\n    def csrf_ok(self, request: Request, *, require_origin: bool = True) -> bool:\n        # The custom header is the core defense (cross-origin credentialed\n        # requests can't set it). For unsafe methods we *also* pin Origin==Host\n        # (Origin is reliably present there); GET requests may legitimately omit\n        # Origin when same-origin, so the header alone gates them.\n        if request.headers.get(CSRF_HEADER) is None:\n            return False\n        if require_origin:\n            parsed = auth_core.parse_origin(request.headers.get(\"origin\"))\n            if not auth_core.same_origin(parsed, self.effective(request)):\n                return False\n        return True\n\n\n# ── cookie helpers ──────────────────────────────────────────────────────────\n\n\ndef _set_session_cookie(resp: Response, token: str, *, ttl_hours: int, secure: bool) -> None:\n    max_age = ttl_hours * 3600 if ttl_hours > 0 else _NEVER_EXPIRE_MAX_AGE\n    resp.set_cookie(\n        COOKIE_NAME,\n        token,\n        max_age=max_age,\n        httponly=True,\n        samesite=\"lax\",\n        path=\"/\",\n        secure=secure,\n    )\n\n\ndef _clear_session_cookie(resp: Response) -> None:\n    resp.set_cookie(COOKIE_NAME, \"\", max_age=0, httponly=True, samesite=\"lax\", path=\"/\")\n\n\ndef _is_secure(gate: AuthGate, request: Request) -> bool:\n    eff = gate.effective(request)\n    return eff is not None and eff[0] == \"https\"\n\n\n# ── whitelist (always-public paths) ─────────────────────────────────────────\n\n\ndef _is_public(request: Request) -> bool:\n    \"\"\"Paths that bypass the gate even when auth is enabled (§4.2).\"\"\"\n    path = request.url.path\n    method = request.method.upper()\n    if method == \"OPTIONS\":\n        return True\n    if not path.startswith(\"/api\"):\n        return True  # static SPA shells, \"/\", favicon, etc.\n    if path in (\"/api/health\", \"/api/qr-info\", \"/api/project-stats\"):\n        return True\n    if path == \"/api/ping\":\n        return True  # pure liveness probe, no sensitive data\n    if path in (\"/api/auth/status\", \"/api/auth/login\", \"/api/auth/extension-token\"):\n        return True\n    if path == \"/api/autostart-status\":\n        return True\n    if path == \"/api/autostart/apply\":\n        return True\n    # guided-init status is remote-readable (can_manage flags local-only); the\n    # write endpoints (init / init/cancel) are whitelisted too but self-gate via\n    # is_trusted_local in their handlers (gui-init spec §2).\n    if path in (\"/api/init-status\", \"/api/init\", \"/api/init/cancel\"):\n        return True\n    # gate management bypasses the middleware so its handler can enforce\n    # trusted-local itself and return a specific 403 local_only for every\n    # non-local caller (remote OR cross-origin loopback), instead of a generic\n    # 401 that leaks whether a token was presented. The handler is the gate.\n    if path == \"/api/auth/admin\":\n        return True\n    # plain logout is public + idempotent; global revoke (?all=true) is NOT.\n    return bool(path == \"/api/auth/logout\" and request.query_params.get(\"all\") != \"true\")\n\n\n# ── middleware ──────────────────────────────────────────────────────────────\n\n\ndef make_auth_middleware(get_gate: GateGetter) -> Any:\n    \"\"\"Build the ASGI http middleware dispatch closure.\"\"\"\n\n    async def auth_guard(request: Request, call_next: Any) -> Any:\n        gate: AuthGate = get_gate()\n        if _is_public(request):\n            return await call_next(request)\n        if gate.is_trusted_local(request):\n            return await call_next(request)\n        if not gate.auth.enabled:\n            # Migration has its own stricter physical-loopback + same-origin\n            # + X-OBC-Auth guard, independent of trust_loopback. Keep local\n            # recovery available when ordinary loopback bypass is disabled.\n            if request.url.path in {\n                \"/api/migration/export\",\n                \"/api/migration/import\",\n                \"/api/migration/status\",\n                \"/api/migration/pending\",\n            }:\n                return await call_next(request)\n            return _cors_echo(\n                JSONResponse(\n                    {\n                        \"error\": \"auth_setup_required\",\n                        \"detail\": \"请先在运行后端的电脑上设置访问密码，再从其他设备连接。\",\n                    },\n                    status_code=401,\n                )\n            )\n\n        used_cookie, token = gate.pick_token(request)\n        # Fallback: <img src> cannot carry cookies (cross-origin) or custom\n        # headers.  Accept a query-param token ONLY on the image-proxy path.\n        # This is intentionally NOT a general-purpose auth mechanism — every\n        # other endpoint still requires cookie / bearer / extension origin.\n        # The token must still pass full validation (signature + epoch + expiry).\n        if not token and request.url.path == \"/api/image-proxy\":\n            token = request.query_params.get(\"token\") or None\n        try:\n            valid = gate.token_valid(token)\n        except Exception:  # DB unavailable -> fail closed\n            logger.warning(\"auth: epoch read failed; failing closed\", exc_info=True)\n            return _unauthorized(clear_cookie=False)\n        if not valid:\n            return _unauthorized(clear_cookie=used_cookie)\n\n        method = request.method.upper()\n        is_unsafe = method in _UNSAFE_METHODS\n        if (\n            used_cookie\n            and (is_unsafe or _is_mutating_get(request.url.path))\n            and not gate.csrf_ok(request, require_origin=is_unsafe)\n        ):\n            # Skip CSRF when the request also carries a valid bearer token.\n            # Query tokens are only accepted by the image proxy, which never\n            # reaches this mutating-request path.\n            extra = gate._extract_bearer(request)\n            has_valid_extra_token = False\n            if extra:\n                with contextlib.suppress(Exception):\n                    has_valid_extra_token = gate.token_valid(extra)\n            if not has_valid_extra_token:\n                return _forbidden_csrf()\n        return await call_next(request)\n\n    return auth_guard\n\n\ndef websocket_session_token(gate: AuthGate, websocket: Any) -> str | None:\n    \"\"\"Return the permitted session token for a WebSocket handshake or lifecycle check.\"\"\"\n    _used_cookie, token = gate.pick_token(websocket)\n    if token:\n        return token\n    origin = websocket.headers.get(\"origin\")\n    if auth_core.is_extension_origin(origin) or auth_core.origin_allowed_for_bearer(\n        origin, gate.auth.allowed_bearer_origins\n    ):\n        return websocket.query_params.get(\"token\") or None\n    return None\n\n\ndef authorize_websocket(gate: AuthGate, websocket: Any) -> bool:\n    \"\"\"Authorize a WebSocket handshake (the http middleware does NOT cover ws).\n\n    Must be called *before* ``websocket.accept()``. Mirrors the HTTP gate plus a\n    same-origin (CSWSH) check, since browsers can't set custom headers on a\n    WebSocket handshake. WebSocket exposes the same ``client`` / ``headers`` /\n    ``cookies`` / ``query_params`` / ``url`` attributes the gate reads.\n\n    Header bearer tokens follow :meth:`AuthGate.pick_token`. Browser WebSocket\n    handshakes cannot set that header, so their query token is accepted only\n    from an extension Origin or an explicitly allowed bearer Origin.\n    \"\"\"\n    if not gate.auth.enabled:\n        return gate.is_trusted_local(websocket)\n    if gate.is_trusted_local(websocket):\n        return True\n    token = websocket_session_token(gate, websocket)\n    try:\n        if token and gate.token_valid(token):\n            return True\n    except Exception:\n        logger.warning(\n            \"auth: websocket token validation failed; falling back to origin check\", exc_info=True\n        )\n    origin = websocket.headers.get(\"origin\")\n    if auth_core.is_extension_origin(origin):\n        return False\n    # No query token is allowed for ordinary Web origins. Cookie sessions keep\n    # the existing same-origin / allow-list CSWSH check below.\n    parsed = auth_core.parse_origin(origin)\n    same = auth_core.same_origin(parsed, gate.effective(websocket))\n    allowed_bearer = auth_core.origin_allowed_for_bearer(origin, gate.auth.allowed_bearer_origins)\n    if not (same or allowed_bearer):\n        return False\n    try:\n        return gate.token_valid(token)\n    except Exception:\n        logger.warning(\"auth: websocket epoch read failed; failing closed\", exc_info=True)\n        return False\n\n\ndef _cors_echo(resp: JSONResponse) -> JSONResponse:\n    # middleware short-circuits run outside CORSMiddleware; echo a permissive\n    # header so cross-origin desktop clients can read the status code.\n    resp.headers.setdefault(\"Access-Control-Allow-Origin\", \"*\")\n    return resp\n\n\ndef _unauthorized(*, clear_cookie: bool) -> JSONResponse:\n    resp = JSONResponse({\"error\": \"auth_required\"}, status_code=401)\n    if clear_cookie:\n        _clear_session_cookie(resp)\n    return _cors_echo(resp)\n\n\ndef _forbidden_csrf() -> JSONResponse:\n    return _cors_echo(JSONResponse({\"error\": \"csrf\"}, status_code=403))\n\n\n# ── routes ──────────────────────────────────────────────────────────────────\n\n\ndef register_auth_routes(app: FastAPI, get_gate: GateGetter) -> None:\n    \"\"\"Register ``/api/auth/{status,login,logout}`` on the FastAPI app.\"\"\"\n\n    @app.get(\"/api/auth/status\")\n    async def auth_status(request: Request) -> JSONResponse:\n        gate: AuthGate = get_gate()\n        env_managed = bool(_auth_env_overrides())\n        local = gate.is_trusted_local(request)\n        # can_manage: only a trusted-local caller (extension/local UI/CLI) may\n        # toggle the gate via /api/auth/admin, and not when env-managed.\n        can_manage = local and not env_managed\n        if not gate.auth.enabled:\n            return JSONResponse(\n                {\n                    \"enabled\": False,\n                    \"authenticated\": local,\n                    \"setup_required\": not local,\n                    \"trust_loopback\": gate.auth.trust_loopback,\n                    \"env_managed\": env_managed,\n                    \"can_manage\": can_manage,\n                }\n            )\n        authenticated = local\n        if not authenticated:\n            _used, token = gate.pick_token(request)\n            try:\n                authenticated = gate.token_valid(token)\n            except Exception:\n                authenticated = False\n        return JSONResponse(\n            {\n                \"enabled\": True,\n                \"authenticated\": authenticated,\n                \"trust_loopback\": gate.auth.trust_loopback,\n                \"env_managed\": env_managed,\n                \"can_manage\": can_manage,\n            }\n        )\n\n    @app.post(\"/api/auth/extension-token\")\n    async def exchange_extension_token(request: Request) -> JSONResponse:\n        gate: AuthGate = get_gate()\n        if not gate.auth.enabled:\n            return JSONResponse({\"error\": \"auth_disabled\"}, status_code=400)\n        if not gate.auth.extension_access_enabled:\n            return JSONResponse({\"error\": \"extension_access_disabled\"}, status_code=403)\n\n        client_ip, _local = gate.resolve_client(request)\n        rate_key = client_ip or (request.client.host if request.client else \"unknown\")\n        if gate.rate.is_locked(rate_key):\n            return JSONResponse({\"error\": \"locked\"}, status_code=429)\n        try:\n            body = await request.json()\n        except Exception:\n            body = {}\n        key = str(body.get(\"key\", \"\")) if isinstance(body, dict) else \"\"\n        if not auth_core.verify_extension_access_key(key, gate.auth.extension_access_keys):\n            gate.rate.record_failure(rate_key)\n            return JSONResponse({\"error\": \"invalid_device_key\"}, status_code=401)\n\n        try:\n            token = auth_core.sign_token(\n                gate.auth.session_secret,\n                epoch=gate.current_epoch(),\n                ttl_hours=gate.auth.extension_token_ttl_hours,\n            )\n        except Exception:\n            return JSONResponse({\"error\": \"unavailable\"}, status_code=503)\n        gate.rate.reset(rate_key)\n        return JSONResponse(\n            {\"ok\": True, \"token\": token, \"expires_at\": auth_core.token_expires_at(token)}\n        )\n\n    @app.post(\"/api/auth/login\")\n    async def auth_login(request: Request) -> JSONResponse:\n        gate: AuthGate = get_gate()\n        if not gate.auth.enabled:\n            return JSONResponse({\"ok\": False, \"error\": \"auth_disabled\"}, status_code=400)\n        if auth_core.is_extension_origin(request.headers.get(\"origin\")):\n            return JSONResponse({\"ok\": False, \"error\": \"origin_forbidden\"}, status_code=403)\n        client_ip, _local = gate.resolve_client(request)\n        rate_key = client_ip or (request.client.host if request.client else \"unknown\")\n        if gate.rate.is_locked(rate_key):\n            return JSONResponse({\"ok\": False, \"error\": \"locked\"}, status_code=429)\n        try:\n            body = await request.json()\n        except Exception:\n            body = {}\n        password = str(body.get(\"password\", \"\")) if isinstance(body, dict) else \"\"\n        if not gate.auth.password_hash or not auth_core.verify_password(\n            password, gate.auth.password_hash\n        ):\n            gate.rate.record_failure(rate_key)\n            return JSONResponse({\"ok\": False}, status_code=401)\n        gate.rate.reset(rate_key)\n\n        try:\n            epoch = gate.current_epoch()\n        except Exception:\n            return JSONResponse({\"ok\": False, \"error\": \"unavailable\"}, status_code=503)\n        ttl = gate.auth.session_ttl_hours\n        origin = request.headers.get(\"origin\", \"\")\n\n        # Same-origin Web login uses a cookie; allowed cross-origin Web origins\n        # receive a finite bearer token.\n        req_origin = auth_core.parse_origin(origin)\n        eff = gate.effective(request)\n        is_same = req_origin is None or auth_core.same_origin(req_origin, eff)\n        token = auth_core.sign_token(gate.auth.session_secret, epoch=epoch, ttl_hours=ttl)\n        if is_same:\n            resp = JSONResponse({\"ok\": True})\n            _set_session_cookie(resp, token, ttl_hours=ttl, secure=_is_secure(gate, request))\n            return resp\n        # Cross-origin: require explicit allow-list + finite TTL\n        if not auth_core.origin_allowed_for_bearer(origin, gate.auth.allowed_bearer_origins):\n            return JSONResponse({\"ok\": False, \"error\": \"origin_forbidden\"}, status_code=403)\n        if ttl <= 0:\n            return JSONResponse({\"ok\": False, \"error\": \"bearer_requires_ttl\"}, status_code=400)\n        return JSONResponse(\n            {\"ok\": True, \"token\": token, \"expires_at\": auth_core.token_expires_at(token)}\n        )\n\n    @app.post(\"/api/auth/logout\")\n    async def auth_logout(request: Request) -> JSONResponse:\n        gate: AuthGate = get_gate()\n        resp = JSONResponse({\"ok\": True})\n        _clear_session_cookie(resp)\n        if request.query_params.get(\"all\") == \"true\" and gate.database is not None:\n            # global revoke; middleware already required a valid session here\n            try:\n                gate.database.bump_auth_epoch()\n            except Exception:\n                logger.warning(\"auth: logout-all bump failed\", exc_info=True)\n                return JSONResponse({\"ok\": False, \"error\": \"unavailable\"}, status_code=503)\n        return resp\n\n\n# ── startup reconciliation ──────────────────────────────────────────────────\n\n\ndef ensure_session_secret(auth: ApiAuthConfig) -> bool:\n    \"\"\"Generate a session secret on first enable. Returns True if it changed.\"\"\"\n    if auth.enabled and not auth.session_secret.strip():\n        auth.session_secret = secrets.token_urlsafe(32)\n        return True\n    return False\n\n\ndef reconcile_password_fingerprint(gate: AuthGate, *, plain: str | None) -> None:\n    \"\"\"Bump the revocation epoch if the password changed since last boot (§4.7).\"\"\"\n    auth = gate.auth\n    if not (auth.enabled and auth.password_hash.strip() and auth.session_secret.strip()):\n        return\n    if gate.database is None:\n        return\n    fingerprint = auth_core.password_fingerprint(\n        auth.session_secret, plain=plain, password_hash=auth.password_hash\n    )\n    try:\n        bumped = gate.database.reconcile_password_fingerprint(fingerprint)\n        gate.reconcile_ok = True\n        if bumped:\n            logger.info(\"auth: password change detected, revoked existing sessions\")\n    except Exception:\n        # Could not confirm/revoke a possible password change → fail closed for\n        # all token auth (loopback still works) until a clean reconcile.\n        gate.reconcile_ok = False\n        logger.warning(\n            \"auth: fingerprint reconcile failed; token auth disabled until next \"\n            \"successful reconcile (restart after fixing the data dir)\",\n            exc_info=True,\n        )\n"
    },
    {
      "path": "docs/privacy.md",
      "content": "# OpenBiliClaw 隐私权政策\n\n生效日期：2026-05-31\n更新日期：2026-10-22\n\nOpenBiliClaw 是一个本地优先的跨平台内容发现 AI Agent。浏览器插件的单一用途是：在用户访问已启用浏览器接入的受支持内容平台时，采集用户授权范围内的浏览、互动和内容信号，发送到用户自己配置的 OpenBiliClaw 后端，用于构建个人兴趣画像、改进内容推荐、同步收藏 / 稍后再看状态和展示本地通知。GitHub v1 来源只由后端通过 GitHub 官方 REST API 读取公开仓库，不在 GitHub 页面运行内容脚本，也不申请 GitHub 主机权限或下发浏览器任务。\n\nInstagram 是默认关闭的正式来源：普通 Instagram 页面不做被动行为采集；只有用户启用公开发现或显式选择初始化时，插件才在隔离任务 tab 中执行有界同源只读任务。安全隔离不代表 Meta 授权，部署者仍需自行确认自动采集权限。\n\n直接 topic 页可以复用浏览器现有登录会话，被动解析页面自然返回的公开媒体；登录响应要求作者明确非私密，只上报规范化字段及 `authenticated_topic_observed` 布尔证据，不上传原始追踪字段。匿名路径保留；这不代表匿名路径始终可用，也不代表已审计页面自身的 Recent Searches 前后状态。\n\n本政策说明 OpenBiliClaw 浏览器插件与本地后端如何处理数据。插件不会把数据发送到 OpenBiliClaw 开发者运营的服务器；Chrome Web Store / AMO 发布包默认只声明本机后端权限，数据流向通常是用户本机运行的 OpenBiliClaw 后端。\n\n## 处理的数据类型\n\n插件可能处理以下数据，具体取决于用户启用的平台、登录状态和后端配置：\n\n| 类型 | 示例 | 用途 |\n|------|------|------|\n| 账号与身份相关信息 | 平台用户 ID、昵称、头像、Bilibili / 抖音等站点 cookie 或会话字段；Linux.do 只单独上报登录布尔，`/session/current.json` 确认的当前用户名只在任务 tab 内用于构造个人只读路径 | 让本地后端以用户已登录身份读取用户授权可见的数据，完成初始化画像、历史 / 收藏 / 点赞同步和内容任务 |\n| 身份验证信息 | 受支持站点的登录 cookie、CSRF token 或页面内请求所需 token；Linux.do `_t` 只在浏览器内转换成布尔，其值不上传 | 仅用于用户配置的本地后端访问对应平台，不用于 OpenBiliClaw 开发者服务器 |\n| 网络记录 | 受支持平台的页面 URL、页面标题、访问时间、视频 / 笔记 / 页面 ID | 识别用户正在浏览的内容，生成行为事件和推荐上下文 |\n| 用户活动 | 点击、搜索、滚动、停留时长、观看时长、喜欢 / 不喜欢、收藏、稍后再看、关注等行为 | 构建和更新兴趣画像，改进推荐排序，过滤不感兴趣内容 |\n| 网站内容 | 页面上可见的文字、封面图 URL、视频 / 笔记标题、作者、标签、描述、链接、统计信息等元数据 | 理解内容主题、生成候选池、去重和解释推荐理由 |\n| 用户显式配置的公开 Web recipe 内容 | recipe 名称、入口 URL、exact allowed origins、受限 selector，以及公开 Feed / Sitemap / 静态列表返回的标题、作者、摘要、链接和明确发布时间 | 由本地后端生成 Web discovery 候选；不作为账号行为或画像事件，不读取 Cookie / token / 登录态页面 |\n| V2EX 只读任务字段 | Topic / Node 的公开 ID、标题、URL、作者、Node、时间、回复摘录，以及布尔登录状态 | 执行用户主动触发的四个 bootstrap scope、聚合讨论事件和生成 Node 偏好；不用于站内写操作 |\n| Instagram 只读任务字段 | 公开 media / user ID、canonical URL、caption、作者、封面、权威发布时间；初始化时的 liked / saved / following scope、数字 current-account ID 与 `sessionid` 存在布尔值 | 公开 topic / creator 发现和用户显式触发的近期点赞、收藏、关注初始化；不用于普通浏览追踪或站内写操作 |\n| GitHub 后端只读字段 | 公开仓库的数值 ID、`node_id`、名称、作者、公开 URL、描述、topics、语言、许可证、统计与时间字段；初始化时还可使用公开 username 及其公开 starred 仓库 | 通过 GitHub 官方 REST API 完成公开仓库发现、去重、推荐和用户主动触发的画像初始化；服务端查询强制 `is:public`，返回行仍会再次拒绝非公开仓库，不执行 Star 或其他站内写操作 |\n| 个人通讯 | 用户在 OpenBiliClaw 插件侧边栏聊天框中主动输入的消息；以及用户在受支持平台上**成功提交**的评论正文与 B 站弹幕正文（提交成功后经网络层采集，仅送本机后端） | 与用户配置的本地后端聊天接口交互，帮助查看画像、推荐和设置；用户亲手写的评论 / 弹幕是最强的兴趣表达之一，用于更准确地构建兴趣画像 |\n| 本地配置与 UI 状态 | 后端地址、已关闭提示、插件设置、缓存的后端配置、任务状态 | 保持插件连接、本地偏好和界面状态 |\n| 用户主动创建的迁移包 | 文件配置中的模型 / 来源 API Key 与 token、平台 Cookie、本地 SQLite、画像 / 记忆、历史、图片缓存和白名单桌面偏好；不包含源机整段 API auth（密码 / hash、session secret、设备 key 等） | 仅在用户从本机桌面配置页明确选择导出时，生成供用户自行搬到另一台机器的 `.obcbackup` |\n| 应用内 Tailnet 节点状态与单次入网材料 | 电脑端 tsnet 节点私钥 / 注册状态、节点名、Tailnet IP、最近脱敏运行事件；用户可在本机设置页单次提交 Auth Key，或 OAuth Client Secret + 设备 tag | 仅在用户明确开启 `[tailnet]` 后，让电脑端 OpenBiliClaw 自己加入用户的 tailnet，供 `OpenBiliClaw-mobile` Android / iOS 原生 App 私网访问；入网凭据只在本机私有暂存到下一次启动并经 stdin 交付，API 不回显；Web / Linux / macOS / Windows Flutter 客户端不在此能力范围，也不用于公网 Funnel |\n\n插件不以收集健康信息、财务和付款信息、精确位置数据为目的。如果用户正在访问的网页内容本身包含敏感信息，插件只会在受支持站点和用户启用功能范围内把它作为页面内容信号处理。\n\n## 数据如何使用\n\nOpenBiliClaw 使用上述数据来：\n\n- 识别用户浏览的内容和平台来源。\n- 生成、更新和展示用户兴趣画像。\n- 生成个性化推荐、解释推荐理由，并根据反馈调整后续推荐。\n- 同步收藏、稍后再看、点赞、关注、历史记录等用户主动启用或平台任务需要的数据。\n- 让本地后端执行多平台初始化画像、内容发现、任务调度和通知。\n- 保存插件设置、连接状态和用户明确关闭过的提示。\n\n这些用途均围绕插件的单一用途：为用户自己的 OpenBiliClaw 后端提供内容理解、画像和推荐所需的数据。\n\n## 数据发送到哪里\n\n插件会把数据发送到用户配置的 OpenBiliClaw 后端地址。Chrome Web Store / AMO 发布包默认只声明本机后端权限，通常是：\n\n- `http://127.0.0.1/...`\n- `http://localhost/...`\n\n如果用户在设置中明确配置局域网或自托管后端，插件会请求该 `scheme://host/*` 的可选权限，并使用默认关闭的设备密钥认证连接。WebExtension 权限模型无法跨浏览器限定端口，实际网络请求仍固定到用户配置的端口。\n\n如果用户明确开启应用内 Tailnet，电脑端独立 `tsnet` helper 会连接用户选择的 Tailscale\n协调服务，并在用户自己的 tailnet 中建立节点。Tailscale 服务会处理节点身份、Tailnet 地址、\n登录 / 连通性等控制面元数据；业务 HTTP payload 通过 tailnet 的 WireGuard 链路加密，无法\n直连时可能经过 Tailscale DERP 中继。该路径只监听 tailnet 私网，不启用 Funnel / Serve，\n不会因此生成公网 OpenBiliClaw 地址。它只服务 Android / iOS 原生 App，不改变浏览器扩展或\n其它 Flutter 平台对远程 endpoint、HTTPS 和设备 key 的独立要求。helper 使用\n`ts_omit_logtail,ts_omit_webclient` 构建标签，编译移除 Tailscale 自动诊断日志上传与未使用的\n管理 Web UI，因此不会向 `log.tailscale.com` 上传 helper 诊断日志；代价是无法依赖相应上游\n自动日志支持。这不取消前述控制面 / DERP 联系及元数据处理。Tailscale 的处理规则以用户所用\n控制服务及其隐私政策为准。\n\n本机桌面 Web / 浏览器插件提交的 Tailnet 入网凭据不会写入普通 `config.toml` 或扩展存储。\n后端只允许真实本机 transport 写入，POSIX 下以 `0700` 目录、`0600` 文件原子暂存；下一次启动\n成功交付 helper stdin 后立即删除。`GET /api/config` 只返回“是否有待用凭据”，不会返回凭据、\n登录 URL 或原始错误。OAuth Client Secret 在 Tailscale 控制面仍是可反复签发带授权 tag 节点的\n长期秘密，本地文件删除不等于撤销 Secret；用户应在 Tailscale 后台采用专用最小权限 Client，\n并在不再需要时撤销。\n\nOpenBiliClaw 插件本身不会把数据发送到 OpenBiliClaw 开发者拥有或运营的远程服务器，也不会内置第三方分析、广告或遥测端点。\n\n用户在桌面 Web 或插件「公开 Web」中显式粘贴 URL 并点击探测时，本地后端会先向该 URL 的\nexact origin 发送匿名有界 GET（包括 robots），只为识别公开 Feed、Sitemap 或确定性静态列表并\n返回有界样例与 recipe 草稿；探测不写 recipe、候选、seen、cursor、memory 或 profile。「采用」\n只把草稿回填到本地表单，用户仍须显式点击「添加网站」才保存。保存后，后端才会按 recipe\n调度同一安全链路。所有请求都不携带浏览器 Cookie、Authorization、登录态或环境代理，逐跳服从\nexact origin、robots fail-closed、公共 DNS/socket pin、响应大小和 MIME/parser 上限；插件只调用\n用户自己的后端，不获得或使用任意网站 host permission 来执行这些请求。正式解析出的公开内容会\n进入本地候选池；若用户配置云端 LLM / embedding，后续统一候选评估可能按下段说明把必要内容\n发送给该用户选择的服务商。当前没有无人确认的自动保存、任意 URL 递归 crawl、登录页面或\nJavaScript 执行能力。\n\n数据迁移请求只允许后端验证为本机 loopback 的调用；浏览器请求还必须具备同源意图并明确拒绝扩展 Origin，无 Origin 的本机 CLI / curl 调用仍可通过同一显式请求头契约。导出文件由本机后端返回给本机客户端，导入文件只上传到用户自己的本机后端；OpenBiliClaw 开发者不会接收迁移包。用户后续主动把文件复制到 U 盘、局域网、聊天工具或云盘时，相应传输与保留由用户和所选服务控制。\n\n如果用户在后端中配置了云端大模型、embedding 服务或其他第三方 API，后端可能会把完成画像、总结、推荐解释或语义处理所需的内容发送给这些用户配置的服务提供方。这属于用户后端配置产生的数据流，不是插件直接调用远程代码或遥测服务。用户应同时查看所选服务提供方的隐私政策。\n\n## 本地存储与保留\n\n海外封面缓存未命中且项目网络策略实际选用代理时，后端通过同一代理向 Cloudflare 的固定 `https://1.1.1.1/dns-query` 查询公开 CDN 域名的 A/AAAA 地址，再校验为公网 IP 并固定连接，防止重绑定访问内网。Cloudflare 可见 CDN 域名、查询时间与代理出口地址；不会收到 Instagram 账号、Cookie、封面 URL 的路径/签名参数或画像。DNS 查询不跟随重定向，失败不绕过安全检查。国内 CDN 和 `network.mode=direct` 使用本机 DNS，不走此 DoH 服务；缓存命中不触发查询。这是封面安全传输依赖，不是统计或遥测。\n\n公开 Web / RSS / Atom / JSON Feed 来源在配置实际选择代理时也复用该 DNS 服务：仅查询已批准请求域的公开域名，Cloudflare 可见域名、查询时间及代理出口，不收到订阅路径、文章内容、Cookie 或画像。直连和系统代理排除项通常使用本机 DNS；公开 Web 和 Ego 的公共 DNS 预检若发现域名答案全部为 `198.18.0.0/15` 代理合成地址，也向该服务查询并验证真实公共地址，Cloudflare 可见域名及当前查询出口地址。网站请求仍遵循原路由，Ego 不因此获得 socket pin 保证。文章链接范围本身不触发这些查询或文章抓取。\n\n插件会使用浏览器的本地扩展存储保存设置、连接状态、缓存配置和 UI 状态。OpenBiliClaw 后端会在用户本机或自托管环境中保存配置文件、SQLite 数据库、日志和画像文件。\n\nInstagram 执行中的任务会在扩展 `storage.local` 临时保存有界 task / claim、任务 tab、deadline、分页进度、已归一化内容与待确认的 exact-result outbox，以便浏览器或扩展重启后恢复。后端确认或明确终态拒绝后清理；离线待重试时会继续保留，卸载扩展会清除这些扩展数据。此状态不含 Instagram Cookie、请求头、CSRF、原始 JSON/HTML 或挑战页正文；旧 `storage.session` 状态只迁移一次。\n\n用户主动导出的 `.obcbackup` 是**未加密的敏感 ZIP 文件**，可能包含模型 / 来源 API Key、平台 Cookie、画像和浏览 / 推荐历史。包内 manifest 带成员大小与 SHA-256，只用于完整性校验，不提供保密性。导出会合并磁盘 `config.toml` / `config.local.toml`、移除整段 `[api.auth]`，再写成包内单份可移植配置；因此源机的登录密码 / hash、session secret、设备访问 key 及其它 auth 策略不会进入包。导出同时刻意排除日志、旧备份、embedding / 评测 / 临时缓存、证书、自启动文件、`data/tailnet/` 节点私钥 / 状态和 `data/bin/` 可执行文件（根目录名按大小写不敏感判定）、OpenBiliClaw Web / 扩展访问会话、外部 CLI 凭据和环境变量值；平台登录 Cookie 则属于明确包含的可移植敏感数据。manifest 的 `source_omitted_environment_variables` 只记录源机当时有值、会影响 OpenBiliClaw 的环境变量名称，包括 `OPENBILICLAW_*`、Gemini 标准 Key 变量及系统代理 / CA 变量；导入端另返回 `target_active_environment_variables`，提示目标环境当前仍可能覆盖导入文件。两个列表都不包含变量值。用户应只在可信设备间传递，并及时删除不再需要的副本。\n\n导入后原配置和数据会按存在情况保留为本机 `pre-import-*.bak` 回滚副本，不会自动上传；下一次成功迁移会清理更早的同类迁移副本。目标机整段 `api.auth` 与 `[tailnet]` 是导入基线，因此其门禁、密码、proxy / Origin 策略、Tailnet 开关 / 节点名和 `data/tailnet/` 机器身份不会被源包覆盖；`certs/`、`autostart/`、`tailnet/` 任一目标保留根含嵌套 symlink 时迁移会拒绝继续，不跟随链接复制目录外数据。应用时只从目标机保留 exact 当前平台 Tailnet helper 的普通非 symlink 文件，POSIX 还要求原文件已有执行位，再为可信副本恢复 `0700`；普通文件不会经迁移升级成 executable。随后会轮换文件中的会话签名密钥，并把 prepared DB 的会话撤销 epoch 设为来源与目标当前值最大值再加一、移除来源 password fingerprint，再清空、关闭扩展远程访问配对。这样即使 session secret 由目标环境固定，来源 / 目标旧 Web 会话与设备 key 也不会继续有效。导入暂存可在重启前取消，取消只删除私有 pending 副本，不改当前配置或用户数据。\n\n用户可以通过以下方式控制或删除数据：\n\n- 在浏览器中移除 OpenBiliClaw 插件，或清除插件站点 / 扩展数据。\n- 停止或删除本地 OpenBiliClaw 后端的数据目录。\n- 在插件设置中修改或清空后端地址。\n- 在后端配置中关闭对应平台 source、调度任务、自动刷新或第三方模型服务。\n- 源码 / 一句话安装可运行 `openbiliclaw tailnet disable` 并重启以停止应用内 Tailnet；桌面安装包需完整退出、把运行目录 `config.toml` 的 `[tailnet].enabled` 改为 `false` 后再启动。两种方式都会为方便再次启用而保留本机节点身份。若要彻底删除，应先退出应用、从 Tailnet 管理台移除节点，再删除 `data/tailnet/`。\n- 退出对应内容平台账号或清除浏览器 cookie，阻止插件继续同步该平台登录态。\n\n## 权限说明\n\n插件请求的权限用于完成本地推荐和平台任务，不用于广告、售卖数据或无关追踪：\n\n| 权限 | 用途 |\n|------|------|\n| `activeTab` | 在用户当前打开的受支持平台页面中识别内容并执行必要的页面动作 |\n| `alarms` | 定时重试 cookie 同步、后端连接检查和任务轮询 |\n| `cookies` | 读取用户已登录站点的必要 cookie，并按各来源最小化契约使用；Linux.do `_t` 与 Instagram `sessionid` 都只判断是否存在并上报布尔值，不同步 Cookie value |\n| `notifications` | 显示来自本地后端的推荐、任务或状态通知 |\n| `scripting` | 在受支持平台页面注入内容脚本，采集页面内容和行为信号 |\n| `sidePanel` | 提供 OpenBiliClaw 侧边栏界面 |\n| `storage` | 保存插件设置、本地 UI 状态和后端连接信息 |\n| 主机权限 | 限定在 Bilibili、小红书、抖音、TikTok、YouTube、X、知乎、Reddit、Linux.do、V2EX、微博、Bangumi、Instagram 以及本机 OpenBiliClaw 后端之间处理必要数据；GitHub 不在扩展主机权限中 |\n\nTikTok 的 `*://*.tiktok.com/*` 与 Instagram 的 `https://*.instagram.com/*` 在 Chrome、Firefox、Safari 清单中均作为默认主机权限声明，由浏览器在安装或更新时处理。Instagram 设置保存不再单独请求或撤销站点权限。两个来源为正式可用、默认关闭；用户或管理员可以在浏览器中限制站点访问，运行时仍检查实际权限。声明权限不自动启用来源或周期同步，也不改变现有数据用途。\n\n`https://*.instagram.com/*` 主机权限只用于带任务标记的隔离 tab。公开任务读取有界 topic/hashtag 或明确 creator 页面；初始化先匹配同源账户表单用户名与新鲜 `PolarisViewer` 的用户名和双 ID，再以 GET 读取 saved/following，被动观察原生 Likes 页只读 Bloks 响应。扩展不重放 Bloks POST、不执行其表达式或 Select/Unlike 动作。插件只上报 `sessionid` 存在性；Cookie value、Authorization/CSRF、请求头、原始 JSON/HTML/Bloks、挑战正文和完整历史不会上传。MAIN 桥只发送有界白名单 rows、cursor 与终态证据。扩展不提交 Instagram Search，不执行 like/save/follow/comment/message，不自动处理安全验证；页面自身的上游状态变化仍需独立审计。普通 Instagram 页面不启动 behavior collector。\n\n`http://127.0.0.1/*` 和 `http://localhost/*` 用于连接用户自己的本机 OpenBiliClaw 后端。内容采集脚本只声明在受支持内容平台上运行；发布包不声明 `http://*/*`、`https://*/*` 或 `<all_urls>` 这类所有网站权限。\n\n公开 Web recipe 的上游请求由本地后端发出，不通过扩展 content script，所以该能力不会为扩展\n新增 `<all_urls>` 或 recipe 站点 host permission。桌面 Web / 插件中的 editor 只把 typed recipe\n提交给用户自己的后端。\n\n抖音初始化任务需要识别当前登录账号，才能读取该账号公开可见的发布、收藏、点赞和关注分页。插件可从页面公开的 `#RENDER_DATA` 读取显式登录状态与候选 `sec_uid`，但不会把它直接当成最终身份；同页 MAIN world 会以 `credentials: \"include\"` 调用抖音同源只读 `/aweme/v1/web/user/profile/self/` 接口，只有该接口正面确认的公开 `sec_uid` 才用于分页与同 tab 缓存，冲突时也以它为准。常驻 fetch / XHR tap 不从页面被动请求 URL 提取或记录 `sec_user_id`；只有用户触发 bootstrap 后，页面消息桥才会传递经 `profile/self` 确认的公开 `sec_uid`、请求关联字段和为任务解析出的分页条目。桥不会传递 Cookie、CSRF token，也不会把未裁剪的原始接口响应对象直接转发。两侧 listener 的同窗口同源检查用于减少误接收，不把同页消息误称为可信授权边界。`sec_uid` 仅用于本次用户授权的抖音 bootstrap 分页，结果仍只发送给用户配置的 OpenBiliClaw 后端。\n\n小红书 discover 搜索任务会在后台标签页运行。由于小红书在隐藏标签中可能不挂载搜索结果列表，插件的同页 MAIN world 桥会观察页面自身发出的搜索接口响应，只归一化最多 20 条与页面卡片等价的公开字段（笔记 ID / 链接、标题、作者、封面 URL、发布时间与互动计数）以及既有的内容访问 token，并把这些字段交给该标签页的 isolated task executor；不会修改请求、转发原始响应、读取 Cookie 值或采集搜索结果正文。归一化结果只用于完成用户本地后端下发的 discover 任务，发送目标仍是用户配置的 OpenBiliClaw 后端；DOM 卡片提取保留为接口结构变化时的兜底。\n\n`https://linux.do/*` 主机权限有两个限定用途：在普通页面运行统一行为 adapter；以及在扩展自己创建、带任务标记的隔离 tab 内执行 Linux.do 同源只读任务。任务只允许 GET，支持公开 search / hot / feed / creator / related discovery，以及已登录账号的 bookmarks / likes / read history bootstrap；不会发帖、点赞、收藏、关注、编辑或执行任何其他站内状态变更。个人任务先通过 `GET /session/current.json` 正面确认当前账号，`_t` Cookie 只用于判断“是否可能已登录”，插件发送给后端的始终只是 `logged_in: true|false`。Cookie 值、其他 Cookie、CSRF 数据、原始 JSON/HTML、挑战页正文均不会上传；任务结果只包含归一化后的 topic ID、标题、URL、作者、分类、tags、发布时间、互动统计、scope 计数或结构化错误。为从 MV3 worker 回收或开发热重载中恢复，扩展会在 `chrome.storage.local` 临时保存无凭据的 task payload、runner tab ID 与绝对截止时间；其中可能包含搜索词或公开 topic / creator URL，但不含 Cookie、账号 token 或站点原始响应，并会在任务终态、超时或无效恢复时删除。普通行为采集与任务 executor 互斥：任务 tab 不产生普通浏览事件。\n\n`*://*.bgm.tv/*` 和 `*://*.bangumi.tv/*` 的主机权限仅用于**账号身份识别**：读取页面公开的用户 uid（`CHOBITS_UID`）与导航栏用户名，实现零配置识别你的 Bangumi 账号，供画像初始化时读取你的公开收藏。在这两个站点上插件不读取 Cookie、不采集浏览行为、也不上传任何个人令牌；Bangumi 内容本身由本地后端通过官方匿名只读 API 获取。\n\n`*://*.v2ex.com/*` 的主机权限用于 V2EX 普通页面的只读 Topic / Node 阅读事件，以及用户主动触发的 `bootstrap_profile` / 增量任务。任务页只读取渲染后的公开 DOM：`/member/<username>` 的本人主题、`/member/<username>/replies` 的本人回复、`/my/topics` 的收藏主题和 `/my/nodes` 的收藏 Node。插件会在本地检查 V2EX 的 A2 Cookie 是否存在，但只向用户配置的后端发送 `logged_in` 布尔值，不发送 Cookie 值；可见页面中的用户名作为 `observed` 身份证据单独上报，登出心跳会清除旧 observed username，浏览器证据最多保留 72 小时。V2EX 任务结果只包含经过限制的公开字段（Topic/Node 标识、标题、URL、作者、Node、时间和最多三条代表性回复摘录），不包含页面 HTML、请求头、CSRF/once、私信、密码或浏览器完整历史。扩展只有在确认 route、页面壳和 scope 完整翻页时才上报 complete；本地后端对收藏 Topic / Node 采用连续两次完整快照缺失确认，生成的取消收藏 / 取消关注只作为本地 `retraction` 画像事件，不会向 V2EX 发请求。PAT 验证身份只保存公开 username 与当前 PAT 的单向 fingerprint，最多信任 6 小时；匹配 PAT 被明确拒绝时清除该声明，网络失败不清除。身份冲突时暂停账号数据合并；PAT 原文仍只存在于用户选择的环境变量 / 配置凭据位置。OpenBiliClaw 对 V2EX 严格只读，不发帖、不回复、不感谢、不收藏、不取消收藏、不关注 Node。\n\nGitHub v1 不使用浏览器 Cookie、页面内容脚本、主机权限或任务队列。后端可匿名读取公开仓库；用户主动配置公开 username 时可读取其公开 starred 仓库，也可选用 GitHub PAT 验证 username 并提高官方 API 配额。PAT 只从来源凭据配置或专用环境变量 `OPENBILICLAW_GITHUB_TOKEN` 解析，不读取通用 `GITHUB_TOKEN` / `GH_TOKEN`。写入配置文件的 PAT 可能随用户主动导出的未加密迁移包移动；环境变量值始终不导出。GitHub 数据只用于本地画像、发现与推荐，保存推荐也仅写本地数据库，不会向 GitHub 发出 Star、Unstar 或其他状态变更请求。\n\n## 远程代码\n\nOpenBiliClaw 浏览器插件不使用远程代码。插件运行所需的 JavaScript 会打包在扩展程序包内，不会通过远程 `<script>`、远程模块、远程 Wasm 或 `eval()` 下载并执行第三方代码。\n\n## 数据共享、出售与其他用途\n\nOpenBiliClaw 开发者不会出售用户数据，也不会为了与插件单一用途无关的目的向第三方传输用户数据。OpenBiliClaw 不会为确定信用度、贷款、广告画像或跨站广告追踪而使用或转移用户数据。\n\n用户自行配置的本地后端、第三方模型服务、代理服务或自托管环境由用户控制；这些服务的数据处理规则以用户自己的配置和相应服务提供方政策为准。\n\n## 联系方式\n\n如需报告隐私问题、请求更正说明或提交安全相关反馈，请通过 GitHub Issues 联系项目维护者：\n\n<https://github.com/whiteguo233/OpenBiliClaw/issues>\n\n\n### TikTok 来源验收补全（2026-10-04）\n\nTikTok 的可选 Cookie 同步：扩展在 tiktok.com 检测到 sessionid/sessionid_ss/sid_tt 登录字段后，将该域 Cookie jar 发送至用户配置的后端统一凭据端点。后端验证会话后保存于本地 data/tiktok_cookie.json，用于可选搜索；不上传给开发者，不采集 TikTok 账号历史来初始化画像。限流账本 tiktok_request_state.sqlite3 仅保存请求时隙与冷却时间。\n\nTikTok 封面下载会通过当前网络路由向 Cloudflare DNS-over-HTTPS 查询公开 CDN 域名，以校验并固定连接地址。查询不包含图片路径/签名参数、Cookie、账号信息或画像；封面 HTTP 请求也不携带 TikTok 登录 Cookie。DoH 不可用时该次封面下载失败。\n"
